,p_name=>'Submit Media Transcribe Workflows'
,p_static_id=>'CREATETRANSCRIBEWORKFLOWS'
,p_display_sequence=>40
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_workflow_id       number;',
'    l_request_url       varchar2(32767);',
'',
'BEGIN',
'',
'    -- Get the Speeech AI Endpoint',
'    SELECT ',
'        E.ENDPOINT || ''/20220101/transcriptionJobs''',
'    INTO l_request_url',
'    FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'    WHERE',
'        E.REGION = AC.REGION AND',
'        E.SERVICE = S.ID AND',
'        S.NAME = ''speech'';',
'',
'    APEX_DEBUG.INFO(''Current Conent ID %s'', :CONTENT_ID);',
'    FOR media IN (SELECT * FROM AICD_MEDIA WHERE content_id = :CONTENT_ID)',
'    LOOP',
'',
'        -- Start a new workflow',
'        IF ((media.type = ''Video'') OR (media.type = ''Audio''))',
'        THEN',
'            l_workflow_id := apex_workflow.start_workflow ',
'            (',
'                p_application_id => :APP_ID,',
'                p_static_id      => ''TRANSCRIBE_MEDIA'',',
'                p_parameters     => apex_workflow.t_workflow_parameters',
'                (',
'                    1 => apex_workflow.t_workflow_parameter(static_id => ''APP_ID'',          string_value => :APP_ID),',
'                    2 => apex_workflow.t_workflow_parameter(static_id => ''FILENAME'',        string_value => media.filename),',
'                    3 => apex_workflow.t_workflow_parameter(static_id => ''MEDIA_ID'',        string_value => media.id),',
'                    4 => apex_workflow.t_workflow_parameter(static_id => ''LANG_CODE'',       string_value => media.lang_code),',
'                    5 => apex_workflow.t_workflow_parameter(static_id => ''REQUEST_URL'',     string_value => l_request_url),',
'                    6 => apex_workflow.t_workflow_parameter(static_id => ''REQUESTOR'',       string_value => :REQUESTOR),',
'                    7 => apex_workflow.t_workflow_parameter(static_id => ''AI_SERVICE'',      string_value => :AI_SERVICE),',
'                    8 => apex_workflow.t_workflow_parameter(static_id => ''OCI_CREDENTIAL'',  string_value => :OCI_CREDENTIAL),',
'                    9 => apex_workflow.t_workflow_parameter(static_id => ''OCI_GENAI_CREDENTIAL'',  string_value => :OCI_GENAI_CREDENTIAL),',
'                    10 => apex_workflow.t_workflow_parameter(static_id => ''OCI_OBJSTOR_CREDENTIAL'',  string_value => :OCI_OBJSTOR_CREDENTIAL),',
'                    11 => apex_workflow.t_workflow_parameter(static_id => ''OCI_SPEECH_CREDENTIAL'',  string_value => :OCI_SPEECH_CREDENTIAL),',
'                    12 => apex_workflow.t_workflow_parameter(static_id => ''OCI_VECTOR_CREDENTIAL'',  string_value => :OCI_VECTOR_CREDENTIAL)',
'                ),',
'                p_initiator => :REQUESTOR ,',
'                p_detail_pk => :APEX$WORKFLOW_ID ,',
'                p_debug_level => apex_debug.c_log_level_info ',
'            );',
'',
'            UPDATE AICD_MEDIA',
'            SET',
'                WORKFLOW_ID = l_workflow_id',
'            WHERE ID = media.id;',
'        END IF;',
'    END LOOP;',
'END;',
''))
