,p_workflow_version_id=>wwv_flow_imp.id(14371137589193620)
,p_name=>'Generate GenAI summary and Vector'
,p_static_id=>'GENAIANDVECTOR'
,p_display_sequence=>110
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_prompt    clob;',
'    l_messages    apex_ai.t_chat_messages := apex_ai.c_chat_messages;',
'    l_response   clob;',
'',
'BEGIN',
'',
'    APEX_SESSION.CREATE_SESSION(',
'         p_app_id   => :APP_ID,',
'         p_page_id  => 1,',
'         p_username => :REQUESTOR',
'    );',
'    ',
'    SELECT JSON_ARRAY(TRANSCRIPT) ',
'        INTO l_prompt',
'    FROM AICD_MEDIA',
'    WHERE ID = :MEDIA_ID;',
'',
'    l_response := apex_ai.chat(',
'        p_prompt            => l_prompt,',
'        p_system_prompt     => ''You are an expert in reviewing audio transcript from cloud, software and hardware technology. You will provide a json response with a summary element and a comma sepearated list of the top 5 technology terms used in th'
||'e tags element. If no technology terms are used provide an empty tags element.'',',
'        p_service_static_id => :AI_SERVICE,',
'        p_messages          => l_messages);',
'',
'    APEX_DEBUG.INFO(''Chat response: %s'',l_response);',
'',
'    UPDATE AICD_MEDIA',
'    SET',
'        SUMMARY         = JSON_VALUE(l_response,''$.summary''),',
'        VECTOR_SUMMARY  = TO_VECTOR(JSON_VALUE(l_response,''$.summary'')),',
'        TAGS            = JSON_VALUE(l_response, ''$.tags''),',
'        VECTOR_TAGS     = TO_VECTOR(JSON_VALUE(l_response, ''$.tags''))',
'    WHERE',
'        ID = :MEDIA_ID;',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1470,"y":680},"z":11}'
);
