wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(14835675523684834)
,p_workflow_version_id=>wwv_flow_imp.id(14835092902684829)
,p_name=>'Create Speech Transcription Job'
,p_static_id=>'CREATESPEECHTRANSCRIBEJOB'
,p_display_sequence=>30
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response  clob;',
'    l_body      clob;',
'',
'BEGIN',
'',
'    SELECT',
'        JSON',
'            {',
'               ''compartmentId'' VALUE ac.compartment,',
'               ''displayName'' VALUE REPLACE(:FILENAME,'' '',''-''),',
'               ''inputLocation'' VALUE ',
'               {',
'                  ''locationType'' VALUE ''OBJECT_LIST_INLINE_INPUT_LOCATION'',',
'                  ''objectLocations'' VALUE [ ',
'                  {',
'                     ''bucketName'' VALUE ac.input_location,',
'                     ''namespaceName'' VALUE ac.namespace,',
'                     ''objectNames'' VALUE [:FILENAME]',
'                  }]',
'               },',
'               ''outputLocation'' VALUE',
'               {',
'                  ''bucketName'' VALUE ac.output_location,',
'                  ''namespaceName'' VALUE ac.namespace,',
'                  ''prefix'' VALUE ''whisper''',
'               },',
'               ''modelDetails'' VALUE',
'               {',
'                  ''languageCode'' VALUE :LANG_CODE,',
'                  ''modelType'' VALUE ac.model,',
'                  ''transcriptionSettings'' VALUE',
'                  {',
'                     ''diarization'' VALUE ',
'                     {',
'                        ''isDiarizationEnabled'' VALUE ''true''',
'                     }',
'                  }',
'               }',
'            }',
'    INTO l_body',
'    FROM AICD_OCI_APP_CONFIGURATION ac;',
'',
'    APEX_DEBUG.INFO(''Body for Media  %s'', l_body);',
'',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'    l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'        p_url                   => :REQUEST_URL,',
'        p_http_method           => ''POST'',',
'        p_body                  => l_body,',
'        p_transfer_timeout      => 360,',
'        p_credential_static_id  => :OCI_CREDENTIAL',
'    );',
'',
'    -- Need to update AICD_MEDIA and set the url column',
'    :JOB_ID             := JSON_VALUE(l_response,''$.id'');',
'    :CURRENT_JOB_STATUS := JSON_VALUE(l_response,''$.lifecycleState'');',
'',
'    UPDATE AICD_MEDIA',
'    SET ',
'        PROCESS_JOD_ID  = :JOB_ID,',
'        PROCESS_STATUS  = ''SUBMITTED''',
'    WHERE ID = :MEDIA_ID;',
'    COMMIT;',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":840,"y":390},"z":3}'
);
wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(14835873389684836)
,p_workflow_version_id=>wwv_flow_imp.id(14835092902684829)
