,p_display_sequence=>40
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response  clob;',
'',
'BEGIN',
'',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'    ',
'    l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'        p_url                   => :REQUEST_URL || ''/'' || :JOB_ID,',
'        p_http_method           => ''GET'',',
'        --p_body_blob             => ,',
'        p_credential_static_id  => :OCI_CREDENTIAL',
'    );',
'',
'    -- Need to update AICD_MEDIA and set the url column',
'    APEX_DEBUG.INFO(''Current Media ID %s'', :MEDIA_ID);',
'    :CURRENT_JOB_STATUS := JSON_VALUE(l_response,''$.lifecycleState'');',
'    ',
'    -- Need to get the response but Workflow does not support clobs',
'    -- May need to call this again to be able to parse the job details.',
'',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":840,"y":510},"z":4}'
);
wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(14836069776684838)
,p_workflow_version_id=>wwv_flow_imp.id(14835092902684829)
,p_name=>'Decode Job Status'
,p_static_id=>'DECODEJOBSTATUS'
,p_display_sequence=>50
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- ACCEPTED, IN_PROGRESS, FAILED, SUCCEEDED, DELETED, NEEDS_ATTENTION',
'    vc_status_out   varchar2(50);',
'',
'BEGIN',
'',
'    APEX_DEBUG.INFO(''Current Status is %s'', :CURRENT_JOB_STATUS);',
'    ',
'    SELECT',
'        CASE :CURRENT_JOB_STATUS',
'            WHEN ''ACCEPTED'' THEN ''RUNNING''',
'            WHEN ''IN_PROGRESS'' THEN ''RUNNING''',
'            WHEN ''FAILED'' THEN ''FINISHED''',
'            WHEN ''NEEDS_ATTENTION'' THEN ''FINISHED''',
'            WHEN ''SUCCEEDED'' THEN ''FINISHED''',
'            WHEN ''DELETED'' THEN ''FINISHED''',
'        ELSE ''RUNNING''',
'        END',
'    INTO vc_status_out',
'    FROM DUAL;',
'',
'    APEX_DEBUG.INFO(''Current Status is '' || vc_status_out);',
