wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(14925965024443516)
,p_workflow_version_id=>wwv_flow_imp.id(14835092902684829)
,p_name=>'Load Transcription Blocks'
,p_static_id=>'New_2'
,p_display_sequence=>110
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    p_blob         blob;',
'    l_clob         clob;',
'    l_dest_offsset integer := 1;',
'    l_src_offsset  integer := 1;',
'    l_lang_context integer := dbms_lob.default_lang_ctx;',
'    l_warning      integer;',
'    l_startTime    varchar2(255);',
'    l_sentence     clob := EMPTY_CLOB();',
'',
'BEGIN',
'    /*',
'    SELECT tranblob INTO p_blob ',
'    FROM AICD_MEDIA',
'    WHERE ',
'        ID = :MEDIA_ID;',
'',
'    dbms_lob.createTemporary(lob_loc => l_clob',
'                          ,cache   => false);',
'',
'    dbms_lob.converttoclob(',
'        dest_lob      => l_clob',
'        ,src_blob     => p_blob',
'        ,amount       => dbms_lob.lobmaxsize',
'        ,dest_offset  => l_dest_offsset',
'        ,src_offset   => l_src_offsset',
'        ,blob_csid    => dbms_lob.default_csid',
'        ,lang_context => l_lang_context',
'        ,warning      => l_warning);',
'        */',
'    ',
'    FOR r IN (',
'        SELECT jt.token, jt.startTime, jt.endTime, jt.confidence,jt.speakerIndex',
'        FROM AICD_MEDIA M, JSON_TABLE (',
'            m.tranblob, ''$.transcriptions[0].tokens[*]''',
'            NULL ON EMPTY',
'            COLUMNS',
'            (',
'                token           varchar2(4000)  path ''$.token'',',
'                startTime       varchar2(4000)  path ''$.startTime'',',
'                endTime         varchar2(4000)  path ''$.endTime'',',
'                confidence      number  path ''$.confidence'',',
'                speakerIndex    int     path ''$.speakerIndex''',
'            )',
'        ) jt  WHERE ',
'        ID = :MEDIA_ID',
'    )',
'    LOOP',
'',
'        IF l_sentence = EMPTY_CLOB()',
'            THEN l_sentence := r.token;',
'            ELSE l_sentence := l_sentence || '' '' || r.token;',
'        END IF;',
'',
'        IF l_startTime IS NULL THEN l_startTime := replace(r.startTime,''s'');',
'        END IF;',
'        IF (instr(r.token,''.'') > 0) THEN',
'            BEGIN',
'                ',
'                INSERT INTO AICD_TRANSCRIPT_BLOCKS',
'                    (MEDIA_ID, SPEAKER_INDX, BLOCK, START_ORDER, END_ORDER)',
'                VALUES',
'                    (:MEDIA_ID, r.speakerIndex, l_sentence, l_startTime, replace(r.endTime,''s''));',
'',
'                l_startTime := NULL;',
'                l_sentence  := EMPTY_CLOB();',
'            END;',
'',
'        END IF;',
'',
'    END LOOP;',
'    ',
'END;',
'',
''))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1470,"y":760},"z":31}'
);
