wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(20013097145910315)
,p_workflow_version_id=>wwv_flow_imp.id(19979391251601256)
,p_name=>'Decode Job Status'
,p_static_id=>'DECODEJOBSTATUS'
,p_display_sequence=>50
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- ACCEPTED, IN_PROGRESS, FAILED, SUCCEEDED, DELETED, NEEDS_ATTENTION',
'    vc_status_out   varchar2(50);',
'',
'BEGIN',
'',
'    APEX_DEBUG.INFO(''Current Status is %s'', :CURRENT_JOB_STATUS);',
'    ',
'    SELECT',
'        CASE :CURRENT_JOB_STATUS',
'            WHEN ''ACCEPTED'' THEN ''RUNNING''',
'            WHEN ''IN_PROGRESS'' THEN ''RUNNING''',
'            WHEN ''FAILED'' THEN ''FINISHED''',
'            WHEN ''NEEDS_ATTENTION'' THEN ''FINISHED''',
'            WHEN ''SUCCEEDED'' THEN ''FINISHED''',
'            WHEN ''DELETED'' THEN ''FINISHED''',
'        ELSE ''RUNNING''',
'        END',
'    INTO vc_status_out',
'    FROM DUAL;',
'',
'    APEX_DEBUG.INFO(''Current Status is '' || vc_status_out);',
'    :DECODED_CURRENT_JOB_STATUS := vc_status_out;',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":840,"y":650},"z":5}'
);
