,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response      clob;',
'    l_request_url   varchar2(32767);',
'    l_filename      varchar2(255) := :FILENAME || ''.json'';',
'    l_transcription blob;',
'',
'BEGIN',
'',
'    l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'        p_url                   => :REQUEST_URL || ''/'' || :JOB_ID,',
'        p_http_method           => ''GET'',',
'        --p_body             => '''',',
'        p_credential_static_id  => ''oci_credential''',
'    );',
'',
'    -- Need to update AICD_MEDIA and set the url column',
'    APEX_DEBUG.INFO(''Current status is %s'', JSON_VALUE(l_response,''$.lifecycleState''));',
'',
'    SELECT ',
'        E.ENDPOINT || ''/n/'' || AC.NAMESPACE || ''/b/'' || AC.OUTPUT_LOCATION || ''/o/'' || replace(apex_util.url_encode(JSON_VALUE(l_response,''$.outputLocation.prefix'') || AC.NAMESPACE || ''_'' || AC.INPUT_LOCATION || ''_'' || l_filename),''+'',''%20'')',
'    INTO l_request_url',
'    FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'    WHERE',
'        E.REGION = AC.REGION AND',
'        E.SERVICE = S.ID AND',
'        S.NAME = ''os'';',
'',
'    APEX_DEBUG.INFO(''Requested: %s'',l_request_url);',
'',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'    -- may need to save this to a table to be able to parse correctly.',
'    l_transcription := apex_web_service.make_rest_request_b(',
'        p_url => l_request_url,',
'        p_http_method => ''GET'',',
'        p_credential_static_id => :OCI_CREDENTIAL',
'    );',
'',
'    UPDATE AICD_MEDIA',
'    SET ',
'        TRANJSON = JSON(l_transcription),',
'        TRANSCRIPT = (',
'            SELECT jt.transcript',
'            FROM JSON_TABLE (',
'                l_transcription, ''$.transcriptions[0]''',
'                NULL ON EMPTY',
'                COLUMNS',
'                (',
'                    transcript      clob    path ''$.transcription''',
'                )',
'            ) jt ',
'        )',
'',
'    WHERE',
'        ID = :MEDIA_ID;',
'',
'    COMMIT;',
'',
'END;',
''))
,p_activity_code_language=>'PLSQL'
