wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(20662361589901016)
,p_workflow_version_id=>wwv_flow_imp.id(20605758763869327)
,p_name=>'Generate Full Transcript GenAI summary and Vector'
,p_static_id=>'New_3'
,p_display_sequence=>110
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_prompt        clob;',
'    l_messages      apex_ai.t_chat_messages := apex_ai.c_chat_messages;',
'    l_response      clob;',
'    l_request_url   varchar2(32767);',
'    l_body          clob; ',
'    l_body_b        clob; ',
'    l_body_s        clob; ',
'    l_body_t        clob; ',
'    l_summary       clob;',
'    l_tags          clob; ',
'    --l_vector_b      clob; ',
'    l_vector_s      clob; ',
'    l_vector_t      clob;',
'    l_embe_b        json_array_t;',
'    l_block         clob;',
'',
'BEGIN',
'    --FOR transcripts in (',
'        SELECT TRANSCRIPT INTO l_block',
'        FROM AICD_MEDIA',
'        WHERE ID = :MEDIA_ID;',
'    --LOOP',
'',
'        -- Get the Chat AI Endpoint',
'        SELECT ',
'            E.ENDPOINT || ''/20231130/actions/chat''',
'        INTO l_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''generative-ai-inference'';',
'',
'        APEX_DEBUG.INFO(''Current url is %s'', l_request_url);',
'        ',
'        APEX_DEBUG.INFO(''Summarize the following Text: %s'', l_block);',
'                ',
'        select json_object(',
'            ''compartmentId'' value ac.compartment,',
'            ''servingMode''   value json_object (',
'                ''modelId''       value ''meta.llama-3.1-70b-instruct'',',
'                ''servingType''   value ''ON_DEMAND''',
'            ),',
'            ''chatRequest''   value json_object(',
'                ''messages''  value json_array( ',
'                    json_object(',
'                        ''role''      value ''SYSTEM'',',
'                        ''content''   value json_array (',
'                            json_object(',
'                                ''type''      value ''TEXT'',',
'                                ''text''      value ''You are an expert in reviewing audio text on cloud, software, and hardware technology topics. You will provide a json response with a summary element and a comma separated list of the top 25 technolo'
||'gy terms used in the tags element. If no technology terms are used provide an empty tags element. Provide the response on a single line without any explanation.''',
'                            )',
'                        )',
'                    ),',
'                    json_object(',
'                        ''role''      value ''USER'',',
'                        ''content''   value json_array (',
'                            json_object(',
'                                ''type''      value ''TEXT'',',
'                                ''text''      value l_block',
'                            )',
'                        ) RETURNING CLOB',
'                    ) RETURNING CLOB',
'                ) ,',
'                ''apiFormat''         value ''GENERIC'',',
'                ''maxTokens''         value 600,',
'                ''isStream''          value false,',
'                ''numGenerations''    value 1,',
'                ''frequencyPenalty''  value 0,',
'                ''presencePenalty''   value 0,',
'                ''temperature''       value 1,',
'                ''topP''              value 1.0,',
'                ''topK''              value 1',
'            ) RETURNING CLOB',
'        ) ',
'        INTO l_body',
'        from AICD_OCI_APP_CONFIGURATION AC;',
'        ',
'        APEX_DEBUG.INFO(''Body : %s'', l_body);',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        APEX_DEBUG.INFO(''Get GenAI Summary and Tags'');',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => l_request_url ,',
'            p_http_method           => ''POST'',',
'            p_body                  => l_body,',
'            p_credential_static_id  => :OCI_CREDENTIAL',
'        );',
'',
'        l_response  := replace(replace(replace(l_response,''\'',''''),''":"{"'',''":{"''),''""}"'',''""}'');',
'        APEX_DEBUG.INFO(l_response);',
'        l_summary   := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.summary'');',
'        l_tags      := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.tags'');',
'',
'        ',
'',
'        -- Get the Embeddings AI Endpoint',
'        SELECT ',
'            E.ENDPOINT || ''/20231130/actions/embedText''',
'        INTO l_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''generative-ai-inference'';',
'',
'        APEX_DEBUG.INFO(''Current url is %s'', l_request_url);   ',
'        --Need to loop once for the text block, the summary, and the tags',
'',
'        select ',
'        /*',
'        json_object(',
'            ''compartmentId'' value ac.compartment,',
'            ''servingMode''   value json_object (',
'                ''modelId''       value ''cohere.embed-multilingual-v3.0'',',
'                ''servingType''   value ''ON_DEMAND''',
'            ),',
'            ''inputs''  value json_array( ',
'                l_block',
'            )',
'        ),',
'        */',
'        json_object(',
'            ''compartmentId'' value ac.compartment,',
'            ''servingMode''   value json_object (',
'                ''modelId''       value ''cohere.embed-multilingual-v3.0'',',
'                ''servingType''   value ''ON_DEMAND''',
'            ),',
'            ''inputs''  value json_array( ',
'                l_summary',
'            )',
'        ),json_object(',
'            ''compartmentId'' value ac.compartment,',
'            ''servingMode''   value json_object (',
'                ''modelId''       value ''cohere.embed-multilingual-v3.0'',',
'                ''servingType''   value ''ON_DEMAND''',
'            ),',
'            ''inputs''  value json_array( ',
'                l_tags',
'            )',
'        )',
'        INTO --l_body_b, ',
'            l_body_s, l_body_t',
'        from AICD_OCI_APP_CONFIGURATION AC;',
'        ',
'        --APEX_DEBUG.INFO(''Body : %s'', l_body);',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        /*',
'        APEX_DEBUG.INFO(''Get Text Block embeddings: %s'', l_block);',
'        APEX_DEBUG.INFO(''Body : %s'', l_body_b);',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => l_request_url ,',
'            p_http_method           => ''POST'',',
'            p_body                  => l_body_b,',
'            p_credential_static_id  => ''oci_credential''',
'        );',
'',
'        l_embe_b := json_object_t.parse(l_response).get_array(''embeddings'');',
'',
'        IF l_embe_b IS NOT NULL THEN',
'            APEX_DEBUG.INFO(''Text Block Embeding: %s'',  l_embe_b.get(0).to_clob());',
'            l_vector_b :=  l_embe_b.get(0).to_clob();',
'        END IF;',
'        */',
'',
'        APEX_DEBUG.INFO(''Get Summary embeddings: %s'', l_summary);',
'        APEX_DEBUG.INFO(''Body : %s'', l_body_s);',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => l_request_url ,',
'            p_http_method           => ''POST'',',
'            p_body                  => l_body_s,',
'            p_credential_static_id  => :OCI_CREDENTIAL',
'        );',
'',
'        l_embe_b := json_object_t.parse(l_response).get_array(''embeddings'');',
'',
'        IF l_embe_b IS NOT NULL THEN',
'            APEX_DEBUG.INFO(''Summary Embeding: %s'',  l_embe_b.get(0).to_clob());',
'            l_vector_s :=  l_embe_b.get(0).to_clob();',
'        END IF;',
'',
'        APEX_DEBUG.INFO(''Get Tag embeddings: %s'', l_tags);',
'        APEX_DEBUG.INFO(''Body : %s'', l_body_t);',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => l_request_url ,',
'            p_http_method           => ''POST'',',
'            p_body                  => l_body_t,',
'            p_credential_static_id  => :OCI_CREDENTIAL',
'        );',
'',
'        l_embe_b := json_object_t.parse(l_response).get_array(''embeddings'');',
'',
'        IF l_embe_b IS NOT NULL THEN',
'            APEX_DEBUG.INFO(''Tag Embeding: %s'',  l_embe_b.get(0).to_clob());',
'            l_vector_t :=  l_embe_b.get(0).to_clob();',
'        END IF;',
'',
'        UPDATE AICD_MEDIA',
'        SET',
'            TAGS            = l_tags,',
'            VECTOR_TAGS     = ',
'                CASE WHEN l_vector_t IS NOT NULL THEN TO_VECTOR(l_vector_t) ELSE NULL END,',
'            SUMMARY         = l_summary,',
'            VECTOR_SUMMARY  = ',
'                CASE WHEN l_vector_s IS NOT NULL THEN TO_VECTOR(l_vector_s) ELSE NULL END',
'        WHERE',
'            ID = :MEDIA_ID;',
'',
'        COMMIT;',
'    ',
'    --END LOOP;',
'',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1470,"y":620},"z":11}'
);
wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(20662566699901018)
,p_workflow_version_id=>wwv_flow_imp.id(20605758763869327)
,p_name=>'Load Transcription Blocks'
,p_static_id=>'New_2'
,p_display_sequence=>120
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    p_blob         blob;',
'    l_clob         clob;',
'    l_dest_offsset integer := 1;',
'    l_src_offsset  integer := 1;',
'    l_lang_context integer := dbms_lob.default_lang_ctx;',
'    l_warning      integer;',
'    l_startTime    varchar2(255);',
'    l_sentence     clob := EMPTY_CLOB();',
'',
'BEGIN',
'    insert into AICD_TRANSCRIPT_BLOCKS ',
'    (MEDIA_ID,BLOCK,SPEAKER_INDX, START_ORDER, END_ORDER)',
'    with tokens as (SELECT jt.token, to_number(replace(jt.startTime,''s'')) startTime, to_number(replace(jt.endTime,''s'')) endTime, jt.speakerIndex, rownum token_id, ',
'        ROW_NUMBER() OVER (ORDER BY rownum) -',
'        ROW_NUMBER() OVER (PARTITION BY speakerIndex ORDER BY rownum) AS group_id',
'        FROM AICD_MEDIA M, JSON_TABLE (',
'                m.tranjson, ''$.transcriptions[0]''',
'                NULL ON EMPTY',
'                COLUMNS',
'                (',
'                    transcript      clob    path ''$.transcript'',',
'                    NESTED PATH ''$.tokens[*]''',
'                    COLUMNS',
'                    (',
'                        token           varchar2(4000)  path ''$.token'',',
'                        startTime       varchar2(4000)  path ''$.startTime'',',
'                        endTime         varchar2(4000)  path ''$.endTime'',',
'                        confidence      number  path ''$.confidence'',',
'                        speakerIndex    int     path ''$.speakerIndex''',
'                    )',
'                )',
'            ) jt ',
'            WHERE ',
'                m.ID = :MEDIA_ID',
'            ORDER BY rownum',
'                ',
'    )',
'    SELECT ',
'        :MEDIA_ID media_id,',
'        listagg(token,'' '') WITHIN GROUP (ORDER BY token_id) as sentence,',
'        t.speakerIndex,',
'        min(startTime) as groupStartTime,',
'        max(startTime) as groupEndTime',
'    FROM',
'        tokens t',
'    GROUP BY group_id,speakerIndex',
'    ORDER BY groupStartTime;',
'',
'    COMMIT;',
'     ',
'END;',
'',
''))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1470,"y":750},"z":12}'
);
