'            p_body                  => l_body,',
'            p_credential_static_id  => :OCI_CREDENTIAL',
'        );',
'',
'        l_response  := replace(replace(replace(l_response,''\'',''''),''":"{"'',''":{"''),''""}"'',''""}'');',
'        APEX_DEBUG.INFO(l_response);',
'        l_summary   := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.summary'');',
'        l_tags      := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.tags'');',
'',
'/*        ',
