wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(21407374620555031)
,p_workflow_version_id=>wwv_flow_imp.id(21151388644973318)
,p_name=>'Restart Parent'
,p_static_id=>'RESTARTPARENT'
,p_display_sequence=>170
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_activity_result    wwv_flow_global.vc_map;',
'   l_workflow_state     varchar2(10);',
'   c_rowcount           number;',
'',
'BEGIN',
'    l_activity_result(''TASK_OUTCOME'')   :=  ''COMPLETE'';',
'',
'    APEX_SESSION.CREATE_SESSION(',
'        p_app_id   => :APP_ID,',
'        p_page_id  => 1,',
'        p_username => :REQUESTOR',
'    );',
'    ',
'    DBMS_SESSION.SLEEP(DBMS_RANDOM.VALUE(1, 20));',
'    BEGIN',
'',
'        SELECT count(*) ',
'        INTO c_rowcount',
'        FROM APEX_WORKFLOWS',
'        WHERE ',
'            WORKFLOW_ID = :APEX$WORKFLOW_DETAIL_PK AND',
'            STATE_CODE = ''ACTIVE'';',
'            ',
'        IF c_rowcount = 1 THEN',
'            l_workflow_state := APEX_WORKFLOW.GET_WORKFLOW_STATE(',
'                p_instance_id          => :APEX$WORKFLOW_DETAIL_PK',
'            );',
'            ',
'            APEX_DEBUG.INFO(''Parent Workflow state is %s '', l_workflow_state);',
'',
'            APEX_WORKFLOW.CONTINUE_ACTIVITY(',
'                p_instance_id          => :APEX$WORKFLOW_DETAIL_PK,',
'                p_static_id            => ''TRANSCRIBEJOBWAIT'',',
'                p_activity_params      => l_activity_result); ',
'',
'',
'        END IF;',
'        EXCEPTION',
'',
'        WHEN NO_DATA_FOUND THEN',
'            NULL;',
'        WHEN OTHERS THEN',
'            APEX_DEBUG.INFO(''Parent Workflow ID %s already restarted'', :APEX$WORKFLOW_DETAIL_PK);',
'    END;',
'',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1750,"y":1170},"z":17}'
);
