'    l_body_b        clob; ',
'    l_body_s        clob; ',
'    l_body_t        clob; ',
'    l_summary       clob;',
'    l_tags          clob; ',
'    --l_vector_b      clob; ',
'    l_vector_s      clob; ',
'    l_vector_t      clob;',
'    l_embe_b        json_array_t;',
'',
'BEGIN',
'',
'    -- Get the Chat AI Endpoint',
'    SELECT ',
'        E.ENDPOINT || ''/20231130/actions/chat''',
'    INTO l_request_url',
'    FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'    WHERE',
'        E.REGION = AC.REGION AND',
'        E.SERVICE = S.ID AND',
'        S.NAME = ''generative-ai-inference'';',
'',
'    APEX_DEBUG.INFO(''Current url is %s'', l_request_url);',
'',
'    APEX_DEBUG.INFO(''Get GenAI Summary and Tags'');',
'    SELECT dbms_vector_chain.utl_to_generate_text( ',
'     ''You are an expert in reviewing audio text on cloud, software, and hardware technology topics. ',
'     You will provide a json response with a summary element and a comma separated list of the top 25 technology terms used in the tags element. ',
'     If no technology terms are used provide an empty tags element. Provide the response on a single line without any explanation.',
'     This is the text to analyze:'' || TRANSCRIPT, ',
'    JSON(''{ "provider": "ocigenai", ',
'                "credential_name": "'' || :OCI_VECTOR_CREDENTIAL || ''", ',
'                "url": "'' || l_request_url || ''", ',
'                "model": "meta.llama-3.1-70b-instruct" ',
'                }'') ',
'        ) ',
'    INTO l_response',
'    FROM AICD_MEDIA',
'    WHERE ID = :MEDIA_ID;',
'',
'    l_response  := replace(replace(replace(l_response,''\'',''''),''":"{"'',''":{"''),''""}"'',''""}'');',
'    APEX_DEBUG.INFO(l_response);',
'    l_summary   := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.summary'');',
'    l_tags      := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.tags'');',
'',
'    UPDATE AICD_MEDIA',
'    SET',
'        TAGS            = l_tags,',
'        SUMMARY         = l_summary',
'    WHERE',
'        ID = :MEDIA_ID;',
'',
'    COMMIT;',
'',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1470,"y":630},"z":12}'
);
