wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(14639302219140580)
,p_workflow_version_id=>wwv_flow_imp.id(71136929106096595)
,p_name=>'Generate GenAI summary and Vector'
,p_static_id=>'GENAIANDVECTOR'
,p_display_sequence=>110
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_prompt    clob;',
'    l_messages    apex_ai.t_chat_messages := apex_ai.c_chat_messages;',
'    l_response   clob;',
'',
'BEGIN',
'    SELECT JSON_ARRAY(TRANSCRIPT) ',
'        INTO l_prompt',
'    FROM AICD_MEDIA',
'    WHERE ID = :MEDIA_ID;',
'',
'    l_response := apex_ai.chat(',
'        p_prompt            => l_prompt,',
'        p_system_prompt     => ''You are an expert in reviewing audio transcript from cloud, software and hardware technology. You will provide a json response with a summary element and a comma sepearated list of the top 5 technology terms used in th'
||'e tags element. If no technology terms are used provide an empty tags element.'',',
'        p_service_static_id => :AI_SERVICE,',
'        p_messages          => l_messages);',
'',
'    UPDATE AICD_MEDIA',
'    SET',
'        SUMMARY         = JSON_VALUE(l_response,''$.summary''),',
'        VECTOR_SUMMARY  = TO_VECTOR(JSON_VALUE(l_response,''$.summary'')),',
'        TAGS            = JSON_VALUE(l_response, ''$.tags''),',
'        VECTOR_TAGS     = TO_VECTOR(JSON_VALUE(l_response, ''$.tags''))',
'    WHERE',
'        ID = :MEDIA_ID;',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1470,"y":680},"z":25}'
);
wwv_flow_imp_shared.create_workflow_activity(
 p_id=>wwv_flow_imp.id(14639858247140585)
,p_workflow_version_id=>wwv_flow_imp.id(71136929106096595)
,p_name=>'Save Media Transcript'
,p_static_id=>'SAVEMEDIATRANSCRIPT'
,p_display_sequence=>100
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response      clob;',
'    l_request_url   varchar2(32767);',
'    l_filename      varchar2(255) := :FILENAME || ''.json'';',
'',
'BEGIN',
'',
'    l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'        p_url                   => :REQUEST_URL || ''/'' || :JOB_ID,',
'        p_http_method           => ''GET'',',
'        --p_body             => '''',',
'        p_credential_static_id  => ''oci_credential''',
'    );',
'',
'    -- Need to update AICD_MEDIA and set the url column',
'    APEX_DEBUG.INFO(''Current status is %s'', JSON_VALUE(l_response,''$.lifecycleState''));',
'',
'    SELECT ',
'        E.ENDPOINT || ''/n/'' || AC.NAMESPACE || ''/b/'' || AC.OUTPUT_LOCATION || ''/o/'' || replace(apex_util.url_encode(JSON_VALUE(l_response,''$.outputLocation.prefix'') || AC.NAMESPACE || ''_'' || AC.INPUT_LOCATION || ''_'' || l_filename),''+'',''%20'')',
'    INTO l_request_url',
'    FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'    WHERE',
'        E.REGION = AC.REGION AND',
'        E.SERVICE = S.ID AND',
'        S.NAME = ''os'';',
'',
'    APEX_DEBUG.INFO(''Requested: %s'',l_request_url);',
'',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'    FOR jlines IN',
'    (SELECT col003 transcript',
'    FROM TABLE( ',
'              apex_data_parser.parse(',
'                  p_content         => apex_web_service.make_rest_request_b',
'                     (p_url => l_request_url,',
'                      p_http_method => ''GET'',',
'                      p_credential_static_id => :OCI_CREDENTIAL),',
'                  p_file_name       => l_filename) ) )',
'    LOOP',
'        APEX_DEBUG.INFO(''Transcription text: %s'', jlines.transcript );',
'        UPDATE AICD_MEDIA',
'        SET',
'            TRANSCRIPT = jlines.transcript',
'        WHERE ',
'            ID = :MEDIA_ID;',
'    END LOOP;',
'',
'END;',
''))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":1470,"y":560},"z":23}'
);
