prompt --application/shared_components/plugins/process_type/com_oracle_ateam_apex_ociobjstor_upload
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(70893815636668752)
,p_plugin_type=>'PROCESS TYPE'
,p_name=>'COM.ORACLE.ATEAM.APEX.OCIOBJSTOR.UPLOAD'
,p_display_name=>'Upload Object to OCI Object Storage'
,p_supported_component_types=>'APEX_APPL_AUTOMATION_ACTIONS:APEX_APPL_WORKFLOW_ACTIVITIES'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('PROCESS TYPE','COM.ORACLE.ATEAM.APEX.OCIOBJSTOR.UPLOAD'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION upload_objects (',
'    p_process IN apex_plugin.t_process,',
'    p_plugin  IN apex_plugin.t_plugin )',
'    RETURN apex_plugin.t_process_exec_result',
'IS  ',
'    c_content_id        constant varchar2(32767) := p_process.attribute_01 ;',
'    c_credential        constant varchar2(32767) := p_process.attribute_03 ;',
'    l_result            apex_plugin.t_process_exec_result;',
'    l_params            wwv_flow_global.vc_map;',
'    l_request_url       varchar2(32767);',
'    n_content_id        number;',
'    l_file_url          varchar2(32767);',
'    l_response          clob;',
'',
'    l_request_id        number;',
'    l_workflow_data     wwv_flow_t_varchar2;',
'    ',
'BEGIN',
'    -- fetch the workflow instance id from the correlation context.',
'    l_workflow_data          := wwv_flow_string.split(',
'        p_str                => p_process.correlation_context,',
'        p_sep                => '':'');',
'    l_request_id    := to_number(l_workflow_data(2));',
'    apex_debug.info(''l_request_id: ''|| l_request_id);',
'    apex_debug.info(''Content data: ''|| APEX_STRING.PLIST_TO_JSON_CLOB(l_workflow_data));',
'',
'    SELECT ',
'        E.ENDPOINT || ''/n/'' || AC.NAMESPACE || ''/b/'' || AC.INPUT_LOCATION || ''/o/''',
'    INTO l_request_url',
'    FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'    WHERE',
'        E.REGION = AC.REGION AND',
'        E.SERVICE = S.ID AND',
'        S.NAME = ''os'';',
'',
'    APEX_DEBUG.INFO(''Current Conent ID %s'', c_content_id);',
'',
'    n_content_id := to_number(trim(c_content_id));',
'',
'    FOR media IN (SELECT * FROM AICD_MEDIA ',
'        WHERE ',
'            content_id = n_content_id AND',
'            url is null)',
'    LOOP',
'        l_file_url := l_request_url || replace(apex_util.url_encode(media.filename),''+'',''%20'') ;',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := media.mime_type;',
'',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => l_file_url,',
'            p_http_method           => ''PUT'',',
'            p_body_blob             => media.blob_contents,',
'            p_transfer_timeout      => 360,',
'            p_credential_static_id  => c_credential',
'        );',
'',
'        -- Need to update AICD_MEDIA and set the url column',
'        APEX_DEBUG.INFO(''Current Media ID %s'', media.id);',
'',
'        UPDATE AICD_MEDIA',
'        SET URL = l_file_url',
'        WHERE ID = media.id;',
'        COMMIT;',
'',
'    END LOOP;',
'',
'    --l_result.success_message := ''SUCCESS'';    ',
'    l_params(''UPLOAD_OUTCOME'') := ''SUCCESS'';',
'/*',
'    apex_workflow.continue_activity(',
'            p_instance_id       => l_request_id,',
'            p_static_id         => ''UPLOADCONTENTFILES'',',
'            p_activity_params   => l_params);',
'*/',
'    RETURN l_result;',
'',
'END;',
'',
'FUNCTION upload_complete (',
'    p_process IN apex_plugin.t_process,',
'    p_plugin  IN apex_plugin.t_plugin,',
'    p_param   IN apex_plugin.t_process_complete_param )',
'    RETURN apex_plugin.t_process_complete_result',
'IS',
'',
'    c_outcome           constant varchar2(32767) := p_process.attribute_02 ;',
'    c_content_id        constant varchar2(32767) := p_process.attribute_01 ;',
'    l_result            apex_plugin.t_process_complete_result;',
'    l_request_id        number;',
'    l_outcome           number;',
'    l_value_map         wwv_flow_global.vc_map   := p_param.value_map;',
'    l_workflow_data     wwv_flow_t_varchar2;',
'    ',
'BEGIN',
'    -- fetch the workflow instance id from the correlation context.',
'    l_workflow_data          := wwv_flow_string.split(',
'        p_str                => p_process.correlation_context,',
'        p_sep                => '':'');',
'    l_request_id    := to_number(l_workflow_data(2));',
'    apex_debug.info(''l_request_id: ''|| l_request_id);',
'    apex_debug.info(''Content data: ''|| APEX_STRING.PLIST_TO_JSON_CLOB(l_workflow_data));',
'',
'    l_result.status           := apex_plugin.c_complete_status_success;',
'',
'    RETURN l_result;',
'END;'))
,p_api_version=>1
,p_execution_function=>'upload_objects'
,p_substitute_attributes=>true
,p_version_scn=>42049831870616
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(71115252410633633)
