wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(14637390642140560)
,p_plug_name=>'Content'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h3:t-ContentBlock--lightBG:t-ContentBlock--hideHeader'
,p_plug_template=>wwv_flow_imp.id(67882948722200396)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ac.ID,',
'   ac.TITLE,',
'   ac.TYPE,',
'   ac.DESCRIPTION,',
'   ac.SCHEDULED_DAY,',
'   ac.SCHEDULED,',
'   ac.TAGS,',
'   ac.SUMMARY,',
'   ac.ACTIONS,',
'   ac.VECTOR_DESCRIPTION,',
'   ac.VECTOR_TAGS,',
'   ac.VECTOR_SUMMARY,',
'   ac.WORKFLOW_ID,',
'   wf.workflow_id WF_ID,',
'   nvl(wf.badge_text, ''Completed'') as badge_text,',
'   case lower(nvl(wf.badge_text, ''Completed''))',
'        when ''active'' then ''fa-ai-generative''',
'        when ''suspended'' then ''fa-pause-circle-o''',
'        when ''completed'' then ''fa-check-circle-o''',
'        when ''terminated'' then ''fa-exclamation-circle-o''',
'        when ''faulted'' then ''fa-exclamation-circle-o''',
'        else ''a-check-circle-o''',
'   end as badge_icon,',
'   decode (wf.badge_text, NULL ,nvl(wf.badge_state,''success''),wf.badge_state) as badge_state,',
'   ac.CREATED,',
'   ac.CREATED_BY,',
'   ac.UPDATED,',
'   ac.UPDATED_BY',
'from AICD_CONTENTS ac, table ( apex_workflow.get_workflows (',
'               p_context => ''ADMIN_WORKFLOWS''',
'               , p_application_id => :APP_ID',
'               ) ) wf',
'where ac.workflow_id = wf.workflow_id(+)'))
,p_query_order_by_type=>'ITEM'
,p_query_order_by=>'{"orderBys":[{"key":"UPDATED","expr":"UPDATED DESC"}],"itemName":"P100_ORDER_BY"}'
