,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    L_COLLECTION_NAMES APEX_APPLICATION_GLOBAL.VC_ARR2 := APEX_STRING.STRING_TO_TABLE(',
'           :APP_SESSION || ''_LANG_CODES,'','',''',
'    );',
'BEGIN',
'    FOR I IN 1..L_COLLECTION_NAMES.COUNT LOOP',
'        BEGIN',
'            ',
'            APEX_DEBUG.INFO(L_COLLECTION_NAMES(I));',
'            IF APEX_COLLECTION.COLLECTION_EXISTS(P_COLLECTION_NAME => L_COLLECTION_NAMES(I)) THEN',
'                APEX_COLLECTION.DELETE_COLLECTION(P_COLLECTION_NAME => L_COLLECTION_NAMES(I));',
'            END IF;',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                -- Add your error handling logic here',
'                NULL; ',
'        END;',
'    END LOOP;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>57107999226465035
);
