,p_process_sequence=>30
,p_parent_process_id=>wwv_flow_imp.id(70815471505010599)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Media Files'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'',
'    insert into aicd_media',
'        (CONTENT_ID, FILENAME, TYPE, LANG_CODE, MIME_TYPE,BLOB_CONTENTS)',
'    select',
'        :P101_ID,at.filename,',
'        case ',
'            when at.mime_type like ''audio%'' then ''Audio''',
'            when at.mime_type like ''video%'' then ''Video''',
'            when at.mime_type like ''image%'' then ''Image''',
'            else ''Document''',
'        end ',
'        ,ac.c002,at.mime_type,at.blob_content',
'    from apex_application_temp_files at, apex_collections ac',
'    where',
'        at.filename = ac.c001 and',
'        collection_name = :APP_SESSION || ''_LANG_CODES'';',
'',
'    commit;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(70712445592608764)
,p_internal_uid=>57108209303465038
);
