begin
wwv_flow_imp_page.create_page(
 p_id=>102
,p_name=>'View Content'
,p_alias=>'VIEW-CONTENT'
,p_page_mode=>'MODAL'
,p_step_title=>'View Content'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_step_template=>wwv_flow_imp.id(67847402975200377)
,p_page_template_options=>'#DEFAULT#'
,p_dialog_width=>'70%'
,p_dialog_chained=>'N'
,p_protection_level=>'C'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<head>',
'    <meta charset="UTF-8">',
'    <meta name="viewport" content="width=device-width, initial-scale=1.0">',
'    <title>View Content</title>',
'</head>',
'<div>',
'    <h2>View Content</h2>',
'    <p>Use this page to view content items and upload associated content files.</p>',
'    <p>When viewing previously added content:</p>',
'    <ul>',
'        <li>The processing status of the content file and its name are provided.</li>',
'        <li>Select a content item to view additional details and associated content files.</li>',
'        <li>Use the sub-menu to view the status of the content processing workflow.</li>',
'    </ul>',
'</div>',
''))
,p_page_component_map=>'27'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(14374806901193657)
,p_plug_name=>'Content'
,p_region_name=>'CONTENTOBJECTS'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h1'
,p_plug_template=>wwv_flow_imp.id(67882948722200396)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select AM.ID,',
'       AM.CONTENT_ID,',
'       AM.FILENAME,',
'       AM.TYPE,',
'       AM.LANG_CODE,',
'       AM.URL,',
'       AM.MIME_TYPE,',
'       case regexp_substr(lower(AM.FILENAME), ''[^.]+$'')',
'            when ''doc'' then ''fa-file-word-o u-color-1-text''',
'            when ''docx'' then ''fa-file-word-o u-color-1-text''',
'            when ''png'' then ''fa-file-image-o u-color-8-text''',
'            when ''pptx'' then ''fa-file-powerpoint-o u-color-4-text''',
'            when ''xls'' then ''fa-file-excel-o u-color-5-text''',
'            when ''xlsx'' then ''fa-file-excel-o u-color-5-text''',
'            when ''aac'' then ''fa-music u-color-8-text''',
'            when ''ac3'' then ''fa-music u-color-8-text''',
'            when ''amr'' then ''fa-music u-color-8-text''',
'            when ''au'' then ''fa-music u-color-8-text''',
'            when ''flac'' then ''fa-music u-color-8-text''',
'            when ''oga'' then ''fa-music u-color-8-text''',
'            when ''m4a'' then ''fa-music u-color-8-text''',
'            when ''mp3'' then ''fa-music u-color-8-text''',
'            when ''wav'' then ''fa-music u-color-8-text''',
'            when ''mkv'' then ''fa-film u-color-13-text''',
'            when ''mp4'' then ''fa-film u-color-13-text''',
'            when ''ogg'' then ''fa-film u-color-13-text''',
'            when ''webm'' then ''fa-film u-color-13-text''',
'            else ''fa-file-o''',
'        end as icon,',
'       AM.BLOB_CONTENTS,',
'       AM.TRANJSON,',
'       AM.PROCESS_JOB_ID,',
'       AM.PROCESS_STATUS,',
'       AM.TRANSCRIPT,',
'       AM.SUMMARY,',
'       AM.VECTOR_SUMMARY,',
'       AM.TAGS,',
'       AM.VECTOR_TAGS,',
'       AM.WORKFLOW_ID,',
'       WF.WORKFLOW_ID WF_ID,',
'       AM.CREATED,',
'       AM.CREATED_BY,',
'       AM.UPDATED,',
'       AM.UPDATED_BY,',
'       nvl(wf.badge_text, ''Completed'') as badge_text,',
'       case lower(nvl(wf.badge_text, ''Completed''))',
'            when ''active'' then ''fa-ai-generative''',
'            when ''suspended'' then ''fa-pause-circle-o''',
'            when ''completed'' then ''fa-check-circle-o''',
'            when ''terminated'' then ''fa-exclamation-circle-o''',
'            when ''faulted'' then ''fa-exclamation-circle-o''',
'            else ''a-check-circle-o''',
'       end as badge_icon,',
'       decode (wf.badge_text, NULL ,nvl(wf.badge_state,''success''),wf.badge_state) as badge_state',
'from AICD_MEDIA AM, table ( apex_workflow.get_workflows (',
'               p_context => ''ADMIN_WORKFLOWS''',
'               , p_application_id => :APP_ID',
'               ) ) wf',
'where am.workflow_id = wf.workflow_id(+) and',
'    AM.CONTENT_ID = :P102_ID',
'order by AM.FILENAME',
''))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_ajax_items_to_submit=>'P102_ID'
,p_plug_query_num_rows=>5
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>true
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_plug_display_when_condition=>'P102_ID'
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'AVATAR_ICON', '&ICON.',
  'AVATAR_SHAPE', 't-Avatar--rounded',
  'AVATAR_TYPE', 'icon',
  'BADGE_COL_WIDTH', 't-ContentRow-badge--md',
  'BADGE_ICON', '&BADGE_ICON.',
  'BADGE_LABEL', 'State',
  'BADGE_LABEL_DISPLAY', 'N',
  'BADGE_SHAPE', 't-Badge--circle',
  'BADGE_SIZE', 't-Badge--md',
  'BADGE_STATE', 'BADGE_STATE',
  'BADGE_STYLE', 't-Badge--outline',
  'BADGE_VALUE', 'BADGE_TEXT',
  'DISPLAY_AVATAR', 'Y',
  'DISPLAY_BADGE', 'Y',
  'HIDE_BORDERS', 'N',
  'MISC', 'Uploaded by: &CREATED_BY.',
  'REMOVE_PADDING', 'N',
  'STYLE', 't-ContentRow--styleCompact',
  'TITLE', '&FILENAME.')).to_clob
);
