wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(13805379007213462)
,p_event_id=>wwv_flow_imp.id(13803922224213456)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_names apex_t_varchar2;',
'    ',
'begin',
'',
'    APEX_DEBUG.INFO(''Uploaded listagg %s'', :P102_FILES);',
'',
'    l_file_names := apex_string.split (',
'                        p_str => :P102_FILES,',
'                        p_sep => '':'' );',
'                        ',
'    IF APEX_COLLECTION.COLLECTION_EXISTS (',
'        p_collection_name => :APP_SESSION || ''_LANG_CODES''',
'        )',
'    THEN',
'        NULL;',
'    ELSE',
'        APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(',
'        p_collection_name => :APP_SESSION || ''_LANG_CODES''',
'        );',
'    END IF;',
'',
'    FOR i IN 1 .. l_file_names.count',
'    LOOP',
'        APEX_DEBUG.INFO(''File %s:'', l_file_names(i));',
'',
'        APEX_COLLECTION.ADD_MEMBER(',
'            p_collection_name   => :APP_SESSION || ''_LANG_CODES'',',
'            p_c001              => l_file_names(i)',
'        );',
'    END LOOP;',
'END;'))
,p_attribute_02=>'P102_FILES'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
