,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_content   varchar2(4000);',
'',
'BEGIN',
'    IF APEX_COLLECTION.COLLECTION_EXISTS (',
'        p_collection_name => :APP_SESSION || ''_LANG_CODES''',
'        )',
'    THEN',
'        NULL;',
'    ELSE',
'        APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(',
'        p_collection_name => :APP_SESSION || ''_LANG_CODES''',
'        );',
'    END IF;',
'',
'    APEX_DEBUG.INFO(''Adding Lang_Code %s for file %s'',APEX_APPLICATION.G_X02, APEX_APPLICATION.G_X01);',
'',
'    APEX_COLLECTION.ADD_MEMBER(',
'        p_collection_name => :APP_SESSION || ''_LANG_CODES'',',
'        p_c001              => APEX_APPLICATION.G_X01,',
'        p_c002              => APEX_APPLICATION.G_X02',
'    );',
'',
'    SELECt JSON_OBJECT(',
'        ''filename'' VALUE APEX_APPLICATION.G_X01,',
'        ''langCode'' VALUE APEX_APPLICATION.G_X02',
'    ) INTO l_content',
'    FROM DUAL;',
'',
'    htp.p(l_content);',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>10407309143441215
);
