'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'',
'    insert into aicd_media',
'        (CONTENT_ID, FILENAME, TYPE, LANG_CODE, MIME_TYPE,BLOB_CONTENTS)',
'    select',
'        :P102_ID,at.filename,',
'        case ',
'            when at.mime_type like ''audio%'' then ''Audio''',
'            when at.mime_type like ''video%'' then ''Video''',
'            else ''Document''',
'        end ',
'        ,ac.c002,at.mime_type,at.blob_content',
'    from apex_application_temp_files at, apex_collections ac',
'    where',
'        at.filename = ac.c001 and',
'        collection_name = :APP_SESSION || ''_LANG_CODES'';',
'',
'    commit;',
'end;'))
