wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(37613466057322171)
,p_plug_name=>'Transcript Blocks Cards'
,p_parent_plug_id=>wwv_flow_imp.id(20489487896527353)
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--styleA'
,p_plug_template=>wwv_flow_imp.id(67881124968200395)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'    MEDIA_ID,',
'    PICK_SPEAKER,',
'    SPEAKER_INDX,',
'    BLOCK,',
'    TAGS,',
'    SUMMARY,',
'    START_ORDER,',
'    END_ORDER,',
'    VECTOR_BLOCK,',
'    VECTOR_TAGS,',
'    VECTOR_SUMMARY,',
'    CREATED,',
'    CREATED_BY,',
'    UPDATED,',
'    UPDATED_BY,',
'    floor(     seconds / 1000 / 60 / 60       ) || ''hrs '' ||',
'    floor( mod(seconds / 1000 / 60      , 60) ) || ''mins '' ||',
'    floor( mod(seconds / 1000           , 60) ) || ''secs '' ||',
'    milliseconds || ''ms'' as timeindex',
'FROM',
'    ( ',
'    select ',
'        ID,',
'        MEDIA_ID,',
'        CASE ',
'           WHEN SPEAKER_ID IS NULL',
'           THEN APEX_ITEM.HIDDEN(',
'            p_idx   => 1,',
'            p_value => ID) ||',
'                APEX_ITEM.SELECT_LIST_FROM_LOV(',
'                    p_idx   => 2,',
'                    p_lov   => ''AICD_SPEAKERS.NAMES'',',
'                    p_null_text     => ''Speaker '' || SPEAKER_INDX,',
'                    p_item_id       => ID',
'                )',
'           ',
'           ELSE',
'                APEX_ITEM.SELECT_LIST_FROM_LOV(',
'                    p_idx   => 2,',
'                    p_value => SPEAKER_ID,',
'                    p_lov   => ''AICD_SPEAKERS.NAMES''',
'                )',
'',
'            END as PICK_SPEAKER,',
'           ',
'            SPEAKER_INDX,',
'            BLOCK,',
'            TAGS,',
'            SUMMARY,',
'            START_ORDER,',
'            END_ORDER,',
'            VECTOR_BLOCK,',
'            VECTOR_TAGS,',
'            VECTOR_SUMMARY,',
'            CREATED,',
'            CREATED_BY,',
'            UPDATED,',
'            UPDATED_BY,',
'            regexp_substr(start_order,''\d*'')  * 1000 + ',
'            regexp_substr(start_order,''[^.]+$'') as seconds,',
'            regexp_substr(start_order,''[^.]+$'') as milliseconds',
'        from AICD_TRANSCRIPT_BLOCKS',
'        where MEDIA_ID = :P103_ID',
'        order by ID',
')   '))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P103_ID'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Transcript Blocks'
,p_prn_page_header_font_color=>'#000000'
