wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20568225786731387)
,p_process_sequence=>60
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE_SPEAKER_IDS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_cur_block     number := apex_application.g_x01;',
'    l_cur_speaker   number := apex_application.g_x02; ',
'    l_media_id      number;',
'    l_speaker_indx  number;',
'BEGIN',
'    ',
'    SELECT SPEAKER_INDX, MEDIA_ID INTO l_speaker_indx, l_media_id',
'    FROM AICD_TRANSCRIPT_BLOCKS',
'    WHERE ',
'        ID = l_cur_block;',
'',
'    APEX_DEBUG.INFO(''##Current Media item %s, Block %s, selected speaker %s'', l_media_id, l_cur_block, l_cur_speaker);',
'',
'    UPDATE AICD_TRANSCRIPT_BLOCKS',
'    SET',
'        SPEAKER_ID = l_cur_speaker',
'    WHERE',
'        MEDIA_ID = l_media_id AND',
'        SPEAKER_INDX = l_speaker_indx;',
'',
'    COMMIT;',
'',
'    htp.p(json_object(''response'' value ''success''));',
'        ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>17177047128959177
);
end;
