,p_process_name=>'Download Media'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_filename     AICD_MEDIA.filename%type;',
'    l_mime_type    AICD_MEDIA.mime_type%type;',
'    l_blob_content AICD_MEDIA.blob_contents%type;',
'begin',
'   select filename, mime_type, blob_contents',
'     into l_filename, l_mime_type, l_blob_content ',
'     from AICD_MEDIA',
'    where id = :P104_MEDIA_ID;',
'  --initialize headers',
'  sys.htp.init;',
'  sys.owa_util.mime_header(l_mime_type, false);',
'  sys.htp.p(''Content-Length: '' || sys.dbms_lob.getlength(l_blob_content));',
'  sys.htp.p(''Content-Disposition: attachment; filename="'' || l_filename || ''"'');',
'  sys.owa_util.http_header_close;',
'  --Download File',
'  sys.wpg_docload.download_file(l_blob_content);',
'  --Stop APEX page processing',
'  apex_application.stop_apex_engine;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>20002063004627939
);
