wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(20439343185370014)
,p_plug_name=>'Transcript Blocks Cards'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--styleC'
,p_plug_template=>wwv_flow_imp.id(67881124968200395)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'       MEDIA_ID,',
'       CASE ',
'           WHEN SPEAKER_ID IS NULL',
'           THEN APEX_ITEM.HIDDEN(',
'            p_idx   => 1,',
'            p_value => ID) ||',
'                APEX_ITEM.SELECT_LIST_FROM_LOV(',
'                    p_idx   => 2,',
'                    p_lov   => ''AICD_SPEAKERS.NAMES'',',
'                    p_null_text     => ''-- Select a Speaker --'',',
'                    p_item_id       => ID',
'                )',
'           ',
'           ELSE',
'                APEX_ITEM.SELECT_LIST_FROM_LOV(',
'                    p_idx   => 2,',
'                    p_value => SPEAKER_ID,',
'                    p_lov   => ''AICD_SPEAKERS.NAMES''',
'                )',
'',
'            END as PICK_SPEAKER,',
'       ',
'       SPEAKER_INDX,',
'       BLOCK,',
'       TAGS,',
'       SUMMARY,',
'       START_ORDER,',
'       END_ORDER,',
'       VECTOR_BLOCK,',
'       VECTOR_TAGS,',
'       VECTOR_SUMMARY,',
'       CREATED,',
'       CREATED_BY,',
'       UPDATED,',
'       UPDATED_BY',
'  from AICD_TRANSCRIPT_BLOCKS',
' where MEDIA_ID = :P710_MEDIA',
' order by ID'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P710_MEDIA'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
