,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE_SPEAKER_IDS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_cur_block     number := apex_application.g_x01;',
'    l_cur_speaker   number := apex_application.g_x02; ',
'    l_cur_media     number := :P710_MEDIA;',
'    l_speaker_indx  number;',
'BEGIN',
'    APEX_DEBUG.INFO(''##Current Medie item %s, Block %s, selected speaker %s'', l_cur_media, l_cur_block, l_cur_speaker);',
'    ',
'    SELECT SPEAKER_INDX INTO l_speaker_indx',
'    FROM AICD_TRANSCRIPT_BLOCKS',
'    WHERE ',
'        ID = l_cur_block;',
'',
'    UPDATE AICD_TRANSCRIPT_BLOCKS',
'    SET',
'        SPEAKER_ID = l_cur_speaker',
'    WHERE',
'        MEDIA_ID = l_cur_media AND',
'        SPEAKER_INDX = l_speaker_indx;',
'',
'    COMMIT;',
'',
'    htp.p(''{"RESPONSE":"Success"'');',
'        ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>16720795124563722
);
