wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(21926408470606124)
,p_event_id=>wwv_flow_imp.id(21925700006606117)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Store Current and previous Chat history'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P800_CHAT_HISTORY'
,p_attribute_01=>'FUNCTION_BODY'
,p_attribute_06=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_combined_result VARCHAR2(32000) := ''''; ',
'    v_json_result     VARCHAR2(32000); ',
'    v_temp     VARCHAR2(32000); ',
'    source_json          JSON_ARRAY_T;',
'    nearest_json        JSON_OBJECT_T;',
'',
'BEGIN ',
'',
'    source_json := new JSON_ARRAY_T;',
' ',
'    FOR rec IN (SELECT block, media_id',
'    FROM AICD_TRANSCRIPT_BLOCKS ',
'    WHERE VECTOR_DISTANCE( VECTOR_BLOCK, to_vector((select embed_vector ',
'    from dbms_vector.UTL_TO_EMBEDDINGS(:P800_QUESTION, ',
'    json(''{ ',
'            "provider": "ocigenai", ',
'            "credential_name": "'' || :G_APP_OCI_VECTOR_CREDENTIAL ||''", ',
'            "url": "''|| :P800_EMDEDTEXT_URL ||''", ',
'            "model": "''|| :P800_EMDEDTEXT_MODEL ||''" ',
'            }'') ), ',
'    JSON_TABLE(column_value, ''$[*]'' COLUMNS (embed_id NUMBER PATH ''$.embed_id'', embed_data VARCHAR2(4000) PATH ''$.embed_data'',  ',
'        embed_vector CLOB PATH ''$.embed_vector'')) et)), COSINE ) < 0.5',
'    FETCH FIRST 5 PARTITIONS BY MEDIA_ID, 5 ROWS ONLY) LOOP ',
' ',
'        v_temp := rec.block; ',
'        source_json.append(new JSON_OBJECT_T(',
'            ''{',
'                    "source_id": "'' || rec.media_id ||''",',
'                    "answer": "'' || rec.block || ''"',
'            }''',
'        ));',
'         ',
'        IF v_combined_result IS NOT NULL THEN ',
'            v_combined_result := v_combined_result || '', ''; ',
'        END IF; ',
' ',
'        v_combined_result := v_combined_result || v_temp; ',
'    END LOOP; ',
' ',
'    APEX_DEBUG.INFO(''Combined Result: %s '', v_combined_result); ',
'    nearest_json := JSON_OBJECT_T.parse(',
'            ''{',
'                    "question": "'' || :P800_QUESTION || ''",',
'                    "answers": '' || source_json.to_string || ''',
'            }''',
'        );',
'    ',
'    v_json_result := json_object( ',
'        ''question'' VALUE :P800_QUESTION, ',
'        ''answer'' VALUE v_combined_result RETURNING VARCHAR2(32000) ',
'    ); ',
'    ',
'    :P800_CHAT_HISTORY      := v_json_result;',
'    :P800_SOURCE_ANSWERS    := nearest_json.to_string;',
'    RETURN v_json_result; ',
'END;'))
,p_attribute_07=>'P800_QUESTION,P800_EMDEDTEXT_URL,P800_EMDEDTEXT_MODEL'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
