,p_event_id=>wwv_flow_imp.id(69981738554746368)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_vc_region             varchar2(255);',
'    l_vc_namespace          varchar2(255);',
'    l_vc_compartment_ocid   varchar2(255);',
'    l_vc_bucket             varchar2(255);',
'BEGIN',
'    ',
'    SELECT IDENTIFIER ',
'    INTO l_vc_region ',
'    FROM AICD_OCI_REGIONS',
'    WHERE ID = :P1000_REGION;',
'',
'    APEX_DEBUG.INFO(''Region is %s'', l_vc_region);',
'    ',
'    ',
'    AICD_OBJSTORAGE.MANAGE_OCI_BUCKETS(',
'        l_vc_credential         => :G_APP_OCI_CREDENTIAL,',
'        l_vc_region             => l_vc_region,',
'        l_vc_namespace          => :P1000_NAMESPACE,',
'        l_vc_compartment_ocid   => :P1000_COMPARTMENT,',
'        vc_request_action       => ''LIST'',',
'        vc_session              => :APP_SESSION',
'    );',
