,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(68111024605200633)
,p_step_template=>wwv_flow_imp.id(67818220321200356)
,p_page_template_options=>'#DEFAULT#:js-dialog-class-t-Drawer--pullOutEnd'
,p_required_patch=>wwv_flow_imp.id(14760629371636740)
,p_dialog_chained=>'N'
,p_protection_level=>'C'
,p_help_text=>'All application help text can be accessed from this page. The links in the "Documentation" region give a much more in-depth explanation of the application''s features and functionality.'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(14761325338636782)
,p_plug_name=>'About Page'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--padded:t-ContentBlock--h1:t-ContentBlock--lightBG'
,p_plug_template=>wwv_flow_imp.id(67882948722200396)
,p_plug_display_sequence=>20
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <h1>About the AI Content Dialog App</h1>',
'</div>',
'<div>',
'    <h2>Exploring AI Services</h2>',
'    <div>',
'        <p>This application was developed to explore the use of Oracle OCI AI Services.</p>',
'        <p>How useful can these services be and how could they be combined in practice for business use cases?</p>',
'    </div>',
'</div>',
'<div>',
'    <div>',
'        <h2>The Use Case</h2>',
'        <p>Provide a simple way for users to have meeting recordings analysed and explored through conversations.</p>',
'        <h2>Capabilities</h2>',
'        <ul>',
'            <li>Upload and storage of content objects</li>',
'            <li>Transcription of audio & video Speech to Text</li>',
'            <li>Generate Summaries and technology Tags</li>',
'            <li>Combine filtered and most relevant enterprise data with GenAI, providing context specific conversations,</li>',
'        </ul>',
'    </div>',
'</div>'))
,p_plug_query_num_rows=>15
,p_plug_display_condition_type=>'ITEM_IS_NULL_OR_ZERO'
,p_plug_display_when_condition=>'P10010_PAGE_ID'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML',
  'show_line_breaks', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(20842699456505834)
,p_plug_name=>'Search Dialog'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(67920659456200411)
,p_plug_display_sequence=>40
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for l_page in ( select page_title,',
'                       help_text',
'                  from apex_application_pages',
'                 where application_id = :APP_ID',
'                   and page_id = :P10010_PAGE_ID )',
'loop',
'    if l_page.help_text is null then',
'        return ''No help is available for this page.'';',
'    else',
'        return case when substr(l_page.help_text, 1, 3) != ''<p>'' then ''<p>'' end ||',
'               apex_application.do_substitutions(l_page.help_text) ||',
'               case when substr(trim(l_page.help_text), -4) != ''</p>'' then ''</p>'' end;',
'    end if;',
'end loop;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_plug_display_condition_type=>'ITEM_NOT_NULL_OR_ZERO'
,p_plug_display_when_condition=>'P10010_PAGE_ID'
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(20842674299505833)
,p_name=>'P10010_PAGE_ID'
,p_item_sequence=>30
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
end;
