prompt --application/deployment/install/install_base_tables
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(14163806288349789)
,p_install_id=>wwv_flow_imp.id(14319052687195820)
,p_name=>'Base Tables'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  CREATE TABLE "AICD_CONFIG" ',
'   (	"ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, ',
'	"PARAM_NAME" VARCHAR2(255 CHAR) NOT NULL ENABLE, ',
'	"PARAM_VALUE" VARCHAR2(4000 CHAR) NOT NULL ENABLE, ',
'	"CREATED" DATE NOT NULL ENABLE, ',
'	"CREATED_BY" VARCHAR2(255 CHAR) NOT NULL ENABLE, ',
'	"UPDATED" DATE NOT NULL ENABLE, ',
'	"UPDATED_BY" VARCHAR2(255 CHAR) NOT NULL ENABLE, ',
'	"DESCRIPTION" VARCHAR2(4000), ',
