'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide Vector Search Services, generating vectors, comparing input to data loaded the AICD_MEDIA & AICD_TRANSCRIPT_BLOCKS tables.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Procedure:      GNERATE_VECTOR',
'-- Description: Creates an AI Speech Transcribe Job and updates the AICD_MEDIA Table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_mode                - Processing mode - media: info is stored in AICD_MEDIA, block:info is stored in AICD_TRANSCRIPT_BLOCKS, NULL: Text as parameter',
'--      @c_text                 - Text as Clob',
'--      @vc_embed_model         - LLM model used to generate embeddings',
'--      @vc_vectorcred          - Credential to be used for the Vector Speech',
'-- =============================================',
'    PROCEDURE GENERATE_VECTOR(',
'        n_media_id      NUMBER,',
'        vc_mode         VARCHAR2 DEFAULT NULL,',
'        c_text          CLOB DEFAULT NULL,',
'        vc_embed_model  VARCHAR2 DEFAULT ''cohere.embed-multilingual-v3.0'',',
'        vc_vectorcred   VARCHAR2',
'    );',
'',
'end "AICD_DBMS_VECTOR";',
'/',
'create or replace package "AICD_AISPEECH" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide integration to OCI AI Speech Service, creation & monitoring of Speech Transcription Jobs and',
'--              retrieval of the job transcript that is loaded into the AICD_MEDIA table.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Function:      CREATE_JOB',
'-- Description: Creates an AI Speech Transcribe Job and updates the AICD_MEDIA Table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_lang_code           - Language Code of the language used in the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION CREATE_JOB(',
'        n_media_id      number,',
'        vc_filename     varchar2,',
'        vc_lang_code    varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential''',
'    ) RETURN varchar2;',
'',
'-- =============================================',
'-- Function:      GET_JOB_STATUS',
'-- Description: Get status of AI Speech Transcribe Job',
'-- Parameters:',
'--      @vc_job_id              - ID of the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_STATUS(',
'        vc_job_id       varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential''',
'    ) RETURN varchar2;',
'',
'-- =============================================',
'-- Function:      GET_JOB_TRANSCRIPTION',
'-- Description: Retrieves AI Speech Transcribe Job Transcription and save it to the AICD_MEDIA table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_job_id              - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'--      @vc_obstorcred          - Credential to be used for the Object Storage service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_TRANSCRIPTION(',
'        n_media_id      number,',
'        vc_job_id       varchar2,',
'        vc_filename     varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential'',',
'        vc_obstorcred   varchar2 default ''oci_credential''',
'    ) RETURN varchar2;',
'',
'end "AICD_AISPEECH";',
'/',
'create or replace package "AICD_OBJSTORAGE" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Create date: October 2024',
'-- Description: Functions supporting REST integration to OCI Object Storage Cloud Service',
'-- Global Parameters:',
'--      @      - None',
'--      ',
'-- =============================================',
'AS',
'-- Package Required Variables',
'-- Package Static Referenced Variables',
'    session_credentials         varchar2(200);',
'',
'-- =============================================',
'-- Procedure:      POST_OBJECT',
'-- Description: Posts an Object to OCI Object Storage',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @l_vc_file_name         - The name of the object stored in the APEX_APPLICATION_TEMP_FILES',
'-- Returns:                         ',
'-- =============================================',
'    procedure POST_OBJECT',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        l_vc_file_name          in varchar2 default null',
'    );',
'',
'',
'-- =============================================',
'-- Procedure:      MANAGE_OCI_BUCKETS',
'-- Description: Manage OCI Storage Buckets: LIST, CREATE, DELETE',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_compartment_ocid  - OCI Compartment OCID',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @vc_request_action      - The requested action ',
'--      @vc_session             - The current APEX session ',
'-- Returns:',
'-- Collections:',
'--                              - [APEX_SESSION]_OCI_BUCKETS_LIST',
'-- Calls:',
'-- Private functions:',
'--      REST_UTIL',
'-- =============================================',
'    PROCEDURE MANAGE_OCI_BUCKETS ',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_compartment_ocid   in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        vc_request_action       in varchar2 default null,',
'        vc_session              in varchar2 default null',
'    );',
'',
'-- =============================================',
'-- Procedure:      MANAGE_OCI_OBJECTS',
'-- Description: Manage OCI Storage Objects: LIST, CREATE, DELETE',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_compartment_ocid  - OCI Compartment OCID',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @l_vc_file_name         - The name of the object stored in the APEX_APPLICATION_TEMP_FILES',
'--      @vc_request_action      - The requested action ',
'--      @vc_session             - The current APEX session ',
'-- Returns:',
'-- Collections:',
'--                              - [APEX_SESSION]_OCI_[BUCKET]_OBJECTS_LIST',
'-- Calls:',
'-- Private functions:',
'--      REST_UTIL',
'-- =============================================',
'    PROCEDURE MANAGE_OCI_OBJECTS',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_compartment_ocid   in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        l_vc_file_name          in varchar2 default null,',
'        vc_request_action       in varchar2 default null,',
'        vc_session              in varchar2 default null',
'    );',
'',
'',
'end "AICD_OBJSTORAGE";',
'/',
'create or replace package body "AICD_DBMS_VECTOR" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide Vector Search Services, generating vectors, comparing input to data loaded the AICD_MEDIA & AICD_TRANSCRIPT_BLOCKS tables.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Procedure:      GNERATE_VECTOR',
'-- Description: Creates an AI Speech Transcribe Job and updates the AICD_MEDIA Table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_mode                - Processing mode - media: info is stored in AICD_MEDIA, block:info is stored in AICD_TRANSCRIPT_BLOCKS, NULL: Text as parameter',
'--      @c_text                 - Text as Clob',
'--      @vc_embed_model         - LLM model used to generate embeddings',
'--      @vc_vectorcred          - Credential to be used for the Vector Speech',
'-- =============================================',
'    PROCEDURE GENERATE_VECTOR(',
'        n_media_id      NUMBER,',
'        vc_mode         VARCHAR2 DEFAULT NULL,',
'        c_text          CLOB DEFAULT NULL,',
'        vc_embed_model  VARCHAR2 DEFAULT ''cohere.embed-multilingual-v3.0'',',
'        vc_vectorcred   VARCHAR2',
'    )',
'    IS',
'        vc_request_url  VARCHAR2(400);',
'        c_block         CLOB;',
'    BEGIN',
'        ',
'        -- Get the Embeddings AI Endpoint',
'        SELECT ',
'            E.ENDPOINT || ''/20231130/actions/embedText''',
'        INTO vc_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''generative-ai-inference'';',
'',
'        APEX_DEBUG.INFO(''Processing Mode => %s using Credential => %s'',vc_mode,vc_vectorcred);',
'        ',
'        CASE LOWER(vc_mode)',
'        -- Generate Emmbeddings for Media',
'        WHEN ''media'' THEN',
'            UPDATE AICD_MEDIA',
'            SET',
'                VECTOR_TAGS     = ',
'                CASE ',
'                WHEN TAGS IS NOT NULL THEN ',
'                    dbms_vector_chain.utl_to_embedding(',
'                        TAGS,',
'                        json(''{',
'                        "provider": "ocigenai",',
'                        "credential_name": "'' || vc_vectorcred || ''",',
'                        "url": "'' || vc_request_url || ''",',
'                        "model": "'' || vc_embed_model || ''"',
'                        }''))',
'                END,',
'                VECTOR_SUMMARY  = ',
'                CASE ',
'                WHEN SUMMARY IS NOT NULL THEN',
'                    dbms_vector_chain.utl_to_embedding(',
'                        SUMMARY,',
'                        json(''{',
'                        "provider": "ocigenai",',
'                        "credential_name": "'' || vc_vectorcred || ''",',
'                        "url": "'' || vc_request_url || ''",',
'                        "model": "'' || vc_embed_model || ''"',
'                        }''))',
'                END',
'            WHERE',
'                ID = n_media_id;',
'        ',
'        -- Generate Emmbeddings for Transcript Blocks',
'        WHEN ''block'' THEN',
'            UPDATE AICD_TRANSCRIPT_BLOCKS',
'            SET',
'                VECTOR_BLOCK     = ',
'                    dbms_vector_chain.utl_to_embedding(',
'                        BLOCK,',
'                        json(''{',
'                        "provider": "ocigenai",',
'                        "credential_name": "'' || vc_vectorcred || ''",',
'                        "url": "'' || vc_request_url || ''",',
'                        "model": "'' || vc_embed_model || ''"',
'                        }''))',
'            WHERE',
'                MEDIA_ID = n_media_id;',
'        ',
'        -- Generate Emmbeddings for generic text',
'        WHEN IS NULL THEN',
'            NULL;',
'        ',
'        END CASE;',
'',
'        COMMIT;',
'    END GENERATE_VECTOR;',
'',
'end "AICD_DBMS_VECTOR";',
'/',
'create or replace package body "AICD_AISPEECH" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide integration to OCI AI Speech Service, creation & monitoring of Speech Transcription Jobs and',
'--              retrieval of the job transcript that is loaded into the AICD_MEDIA table.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Function:      CREATE_JOB',
'-- Description: Creates an AI Speech Transcribe Job',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_lang_code           - Language Code of the language used in the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @b_request_status   - Status of the request',
'-- =============================================',
'FUNCTION CREATE_JOB(',
'    n_media_id      number,',
'    vc_filename     varchar2,',
'    vc_lang_code    varchar2,',
'    vc_request_url  varchar2,',
'    vc_speechcred   varchar2 default ''oci_credential''',
'    ) ',
'    RETURN varchar2',
'    IS',
'        c_body              clob;',
'        c_response          clob;',
'        vc_job_id           varchar2(200);',
'        vc_request_status   varchar2(200);',
'',
'    BEGIN',
'    SELECT',
'        JSON',
'            {',
'               ''compartmentId'' VALUE ac.compartment,',
'               ''displayName'' VALUE REPLACE(vc_filename,'' '',''-''),',
'               ''inputLocation'' VALUE ',
'               {',
'                  ''locationType'' VALUE ''OBJECT_LIST_INLINE_INPUT_LOCATION'',',
'                  ''objectLocations'' VALUE [ ',
'                  {',
'                     ''bucketName'' VALUE ac.input_location,',
'                     ''namespaceName'' VALUE ac.namespace,',
'                     ''objectNames'' VALUE [vc_filename]',
'                  }]',
'               },',
'               ''outputLocation'' VALUE',
'               {',
'                  ''bucketName'' VALUE ac.output_location,',
'                  ''namespaceName'' VALUE ac.namespace,',
'                  ''prefix'' VALUE ''whisper''',
'               },',
'               ''modelDetails'' VALUE',
'               {',
'                  ''languageCode'' VALUE vc_lang_code,',
'                  ''modelType'' VALUE ac.model,',
'                  ''transcriptionSettings'' VALUE',
'                  {',
'                     ''diarization'' VALUE ',
'                     {',
'                        ''isDiarizationEnabled'' VALUE ''true''',
'                     }',
'                  }',
'               }',
'            }',
'    INTO c_body',
'    FROM AICD_OCI_APP_CONFIGURATION ac;',
'',
'    APEX_DEBUG.INFO(''Body for Media  %s'', c_body);',
'',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'    c_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'        p_url                   => vc_request_url,',
'        p_http_method           => ''POST'',',
'        p_body                  => c_body,',
'        p_transfer_timeout      => 360,',
'        p_credential_static_id  => vc_speechcred',
'    );',
'',
'    -- Need to update AICD_MEDIA and set the url column',
'    vc_job_id           := JSON_VALUE(c_response,''$.id'');',
'    vc_request_status   := JSON_VALUE(c_response,''$.lifecycleState'');',
'',
'    -- Update AICD Media Table with job id and submitted status',
'    -- ** Should enclose in TRY/CATCH Block',
'    UPDATE AICD_MEDIA',
'    SET ',
'        PROCESS_JOB_ID  = vc_job_id,',
'        PROCESS_STATUS  = ''SUBMITTED''',
'    WHERE ID = n_media_id;',
'',
'    COMMIT;',
'',
'    RETURN vc_request_status;',
'    END CREATE_JOB;',
'',
'-- =============================================',
'-- Function:      GET_JOB_STATUS',
'-- Description: Get status of AI Speech Transcribe Job',
'-- Parameters:',
'--      @vc_job_id              - ID of the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_STATUS(',
'        vc_job_id       varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential''',
'    ) ',
'    RETURN varchar2',
'    IS',
'        c_response          clob;',
'        vc_request_status   varchar2(200);',
'    BEGIN',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'        ',
'        c_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => vc_request_url || ''/'' || vc_job_id,',
'            p_http_method           => ''GET'',',
'            --p_body_blob             => ,',
'            p_credential_static_id  => vc_speechcred',
'        );',
'',
'        -- Need to update AICD_MEDIA and set the url column',
'        APEX_DEBUG.INFO(''Current Job ID %s'', vc_job_id);',
'        vc_request_status := JSON_VALUE(c_response,''$.lifecycleState'');    ',
'',
'        RETURN vc_request_status;',
'    END GET_JOB_STATUS;',
'',
'-- =============================================',
'-- Function:      GET_JOB_TRANSCRIPTION',
'-- Description: Retrieves AI Speech Transcribe Job Transcription and save it to the AICD_MEDIA table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_job_id              - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'--      @vc_obstorcred          - Credential to be used for the Object Storage service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_TRANSCRIPTION(',
'        n_media_id      number,',
'        vc_job_id       varchar2,',
'        vc_filename     varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential'',',
'        vc_obstorcred   varchar2 default ''oci_credential''',
'    ) ',
'    RETURN varchar2',
'    IS',
'        c_response          clob;',
'        bl_transcription    blob;',
'        vc_file_url         varchar2(4000);',
'        vc_request_status   varchar2(200);',
'    BEGIN',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        c_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => vc_request_url || ''/'' || vc_job_id,',
'            p_http_method           => ''GET'',',
'            p_credential_static_id  => vc_speechcred',
'        );',
'',
'        APEX_DEBUG.INFO(''Current status is %s'', JSON_VALUE(c_response,''$.lifecycleState''));',
'        DBMS_OUTPUT.PUT_LINE(''Current status is:'' || JSON_VALUE(c_response,''$.lifecycleState''));',
'',
'        SELECT ',
'            E.ENDPOINT || ''/n/'' || AC.NAMESPACE || ''/b/'' || AC.OUTPUT_LOCATION || ''/o/'' || replace(apex_util.url_encode(JSON_VALUE(c_response,''$.outputLocation.prefix'') || AC.NAMESPACE || ''_'' || AC.INPUT_LOCATION || ''_'' || vc_filename || ''.json''),''+'''
||',''%20'')',
'        INTO vc_file_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''os'';',
'',
'        APEX_DEBUG.INFO(''Requested: %s'',vc_file_url);',
'        DBMS_OUTPUT.PUT_LINE(''Requested: '' || vc_file_url);',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        -- Save this to a table to be able to parse correctly.',
'        bl_transcription := apex_web_service.make_rest_request_b(',
'            p_url => vc_file_url,',
'            p_http_method => ''GET'',',
'            p_credential_static_id => vc_obstorcred',
'        );',
'',
'        DBMS_OUTPUT.PUT_LINE(''Transcript:'' || JSON_VALUE(bl_transcription,''$.transcriptions[0]''));',
'',
'        UPDATE AICD_MEDIA',
'        SET ',
'            TRANJSON = JSON(bl_transcription),',
'            TRANSCRIPT = (',
'                SELECT jt.transcript',
'                FROM JSON_TABLE (',
'                    bl_transcription, ''$.transcriptions[0]''',
'                    NULL ON EMPTY',
'                    COLUMNS',
'                    (',
'                        transcript      clob    path ''$.transcription''',
'                    )',
'                ) jt ',
'            )',
'',
'        WHERE',
'            ID = n_media_id;',
'',
'        COMMIT;',
'',
'        vc_request_status := ''SUCCESS'';',
'        ',
'        RETURN vc_request_status;',
'    END GET_JOB_TRANSCRIPTION;',
'',
'end "AICD_AISPEECH";',
'/',
'create or replace package body "AICD_OBJSTORAGE" ',
'AS',
'',
'-- =============================================',
'-- Function:      REST_UTIL',
'-- Description: Utility to support Rest Calls, shared across all OCI REST Service calls',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials to use in the REST request',
'--      @l_vc_url               - The URL for the REST request ',
'--      @l_vc_method            - The HTTP method for the REST request',
'--      @l_vc_body              - The Body of the REST request',
'--      @l_vc_type              - The type of REST request [BLOB | CLOB]',
'-- Returns: @l_response         - The Rest Response                        ',
'-- =============================================',
'    FUNCTION REST_UTIL',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_url                in varchar2 default null,',
'        l_vc_method             in varchar2 default null,',
'        l_mime_type             in varchar2 default null,',
'        l_vc_body_c             in clob default empty_clob(),',
'        l_vc_body_b             in blob default empty_blob(),',
'        l_vc_type               in varchar2 default null',
'    )',
'    RETURN clob ',
'    IS ',
'        c_response      clob;',
'',
'    BEGIN',
'',
'        apex_web_service.g_request_headers.delete();',
'        apex_web_service.g_request_headers(1).name := ''Content-Type'';',
'        apex_web_service.g_request_headers(1).value := l_mime_type;',
'',
'        BEGIN',
'            CASE l_vc_type',
'                WHEN ''BLOB'' THEN                    ',
'                    c_response := apex_web_service.make_rest_request(',
'                        p_url                   => l_vc_url,',
'                        p_http_method           => l_vc_method,',
'                        p_body_blob             => l_vc_body_b,',
'                        p_transfer_timeout      => 360,',
'                        p_credential_static_id  => l_vc_credential',
'                    );',
'',
'                    for i in 1.. apex_web_service.g_request_headers.count',
'                    loop',
'                        apex_debug.info(''%s: %s'',apex_web_service.g_headers(i).name,apex_web_service.g_headers(i).value);',
'                    end loop;',
'                ',
'                WHEN ''CLOB'' THEN',
'                    c_response := apex_web_service.make_rest_request(',
'                        p_url                   => l_vc_url,',
'                        p_http_method           => l_vc_method,',
'                        p_body                  => l_vc_body_c,',
'                        p_credential_static_id  => l_vc_credential',
'                    );',
'                    ',
'                    ',
'            END CASE;',
'',
'        EXCEPTION',
'        WHEN OTHERS THEN',
'            APEX_DEBUG.INFO(''Failed submitting service call'');',
'            APEX_DEBUG.INFO(SQLCODE);',
'            APEX_DEBUG.INFO(SUBSTR(SQLERRM, 1, 200));',
'            APEX_DEBUG.INFO(c_response);',
'        END;',
'',
'        RETURN (c_response);',
'',
'    END REST_UTIL;',
'',
'-- =============================================',
'-- Procedure:      POST_OBJECT',
'-- Description: Description: Posts an Object to OCI Object Storage',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @l_vc_file_name         - The name of the object stored in the APEX_APPLICATION_TEMP_FILES',
'-- Returns:                         ',
'-- =============================================',
'    PROCEDURE POST_OBJECT',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        l_vc_file_name          in varchar2 default null',
'    )',
'    IS',
'        l_request_url           varchar2(32767);',
'        l_request_filename      varchar2(500);',
'        l_enc_filename          varchar2(4000);',
'        l_request_content       blob;',
'        l_mime_type             varchar2(200);',
'        l_response              clob;',
'        ',
'    BEGIN',
'        SELECT ',
'            blob_content,filename, mime_type ',
'        INTO ',
'            l_request_content,l_request_filename, l_mime_type ',
'        FROM apex_application_temp_files',
'        WHERE',
'            name = l_vc_file_name;',
'',
'        l_enc_filename := replace(apex_util.url_encode(l_request_filename),''+'',''%20'');',
'        ',
'        --l_request_url := ''https://objectstorage.'' || l_vc_region || ''/n/'' || l_vc_namespace || ''/b/'' || l_vc_bucket || ''/o/'' ||l_enc_filename;',
'',
'        SELECT ',
'            ENDPOINT || ''/n/'' || l_vc_namespace || ''/b/'' || l_vc_bucket || ''/o/'' ||l_enc_filename',
'        INTO l_request_url',
'        FROM AICD_OCI_REGIONAL_ENDPOINTS',
'        WHERE',
'            REGION  = l_vc_region AND',
'            SERVICE = ''os'';',
'',
'        APEX_DEBUG.INFO(''URL: %s'',l_request_url);',
'        APEX_DEBUG.INFO(''MIME Type: %s'',l_mime_type);',
'        ',
'        l_response := REST_UTIL',
'            (',
'                l_vc_credential         => l_vc_credential,',
'                l_vc_url                => l_request_url,',
'                l_vc_method             => ''PUT'',',
'                l_mime_type             => l_mime_type,',
'                l_vc_body_b             => l_request_content,',
'                l_vc_type               => ''BLOB''',
'            );',
'',
'    END POST_OBJECT;',
'',
'-- =============================================',
'-- Procedure:      MANAGE_OCI_BUCKETS',
'-- Description: Manage OCI Storage Buckets: LIST, CREATE, DELETE,',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_compartment_ocid  - OCI Compartment OCID',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @vc_request_action      - The requested action ',
'--      @vc_session             - The current APEX session ',
'-- Returns:',
'-- Collections:',
'--                              - [APEX_SESSION]_OCI_BUCKETS_LIST',
'-- Calls:',
'-- Private functions:',
'--      REST_UTIL',
'-- =============================================',
'    PROCEDURE MANAGE_OCI_BUCKETS ',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_compartment_ocid   in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        vc_request_action       in varchar2 default null,',
'        vc_session              in varchar2 default null',
'    )',
'    IS',
'        l_request_url           varchar2(32767);',
'        l_body                  JSON_OBJECT_T;',
'        c_response              clob;',
'',
'        l_seq_id                number;',
'',
'    BEGIN',
'        --l_request_url := ''https://objectstorage.'' || l_vc_region || ''/n/'' || l_vc_namespace || ''/b/'';',
'',
'        SELECT ',
'            ENDPOINT || ''/n/'' || l_vc_namespace || ''/b/''',
'        INTO l_request_url',
'        FROM AICD_OCI_REGIONAL_ENDPOINTS',
'        WHERE',
'            REGION  = l_vc_region AND',
'            SERVICE = ''os'';',
'',
'        --APEX_DEBUG.INFO(''Request Action: %s on url %s'',vc_request_action, l_request_url);',
'    ',
'        CASE vc_request_action',
'            WHEN ''LIST'' THEN',
'                BEGIN',
'                    APEX_DEBUG.INFO(''Attempting to Get List of Buckets'');',
'                    ',
'                    c_response := REST_UTIL',
'                    (',
'                        l_vc_credential         => l_vc_credential,',
'                        l_vc_url                => l_request_url || ''?compartmentId='' || l_vc_compartment_ocid,',
'                        l_vc_method             => ''GET'',',
'                        l_vc_type    '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(22958680981964031)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'           => ''CLOB''',
'                    );',
'                    ',
'                    -- Create or Trunacte the Collection',
'                    APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(vc_session || ''_OCI_BUCKETS_LIST'');',
'',
'                    FOR buckets IN (',
'                        SELECT BUCKET_NAME ',
'                        FROM JSON_TABLE(',
'                            c_response, ''$[*]''',
'                            NULL ON EMPTY',
'                            COLUMNS (',
'                                BUCKET_NAME  varchar2(255)   path ''$.name''',
'                            )',
'                        )',
'                    )',
'                    LOOP',
'                        -- C001 = BUCKET_NAME',
'                        APEX_COLLECTION.ADD_MEMBER(',
'                            p_collection_name   => vc_session || ''_OCI_BUCKETS_LIST'',',
'                            p_c001              => buckets.BUCKET_NAME',
'                        );',
'                    END LOOP;',
'                END;',
'',
'            WHEN ''CREATE'' THEN',
'                BEGIN',
'                    APEX_DEBUG.INFO(''Attempting to Create OCI Bucket'');',
'',
'                    l_body := JSON_OBJECT_T(''{}'');',
'                    l_body.put(''compartmentId'', l_vc_compartment_ocid);',
'                    l_body.put(''name'', l_vc_bucket);',
'',
'                    ',
'                    c_response := REST_UTIL',
'                    (',
'                        l_vc_credential         => l_vc_credential,',
'                        l_vc_url                => l_request_url,',
'                        l_vc_method             => ''POST'',',
'                        l_vc_body_c             => l_body.to_clob(),',
'                        l_vc_type               => ''CLOB''',
'                    );',
'',
'                    -- C001 = BUCKET_NAME',
'                    APEX_COLLECTION.ADD_MEMBER(',
'                        p_collection_name   => vc_session || ''_OCI_BUCKETS_LIST'',',
'                        p_c001              => l_vc_bucket',
'                    );',
'                END;',
'',
'            WHEN ''DELETE'' THEN',
'                BEGIN',
'                    APEX_DEBUG.INFO(''Attempting to Delete OCI Bucket'');',
'                    ',
'                    c_response := REST_UTIL',
'                    (',
'                        l_vc_credential         => l_vc_credential,',
'                        l_vc_url                => l_request_url || ''/'' || l_vc_bucket,',
'                        l_vc_method             => ''DELETE'',',
'                        l_vc_type               => ''CLOB''',
'                    );',
'',
'                    SELECT ',
'                        seq_id',
'                    INTO',
'                         l_seq_id',
'                    FROM ',
'                        APEX_COLLECTIONS',
'                    WHERE',
'                        collection_name = vc_session || ''_OCI_BUCKETS_LIST'' AND',
'                        c001            = l_vc_bucket;',
'',
'                    APEX_COLLECTION.DELETE_MEMBER(',
'                        p_collection_name   => vc_session || ''_OCI_BUCKETS_LIST'',',
'                        p_seq               => l_seq_id',
'                    );',
'                END;',
'        END CASE;',
'    END MANAGE_OCI_BUCKETS;',
'',
'',
'-- =============================================',
'-- Procedure:      MANAGE_OCI_OBJECTS',
'-- Description: Manage OCI Storage Objects: LIST, CREATE, DELETE',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_compartment_ocid  - OCI Compartment OCID',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @l_vc_file_name         - The name of the object stored in the APEX_APPLICATION_TEMP_FILES',
'--      @vc_request_action      - The requested action ',
'--      @vc_session             - The current APEX session ',
'-- Returns:',
'-- Collections:',
'--                              - [APEX_SESSION]_OCI_[BUCKET]_OBJECTS_LIST',
'-- Calls:',
'-- Private functions:',
'--      REST_UTIL',
'-- =============================================',
'    PROCEDURE MANAGE_OCI_OBJECTS',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_compartment_ocid   in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        l_vc_file_name          in varchar2 default null,',
'        vc_request_action       in varchar2 default null,',
'        vc_session              in varchar2 default null',
'    )',
'    IS',
'    BEGIN',
'        NULL;',
'    END MANAGE_OCI_OBJECTS;',
'',
'end "AICD_OBJSTORAGE";',
'/'))
);
end;
