prompt --application/deployment/install/install_base_views
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(14468187767523420)
,p_install_id=>wwv_flow_imp.id(14319052687195820)
,p_name=>'Base Views'
,p_sequence=>20
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  CREATE OR REPLACE FORCE EDITIONABLE VIEW "AICD_OCI_REGIONAL_ENDPOINTS" ("ID", "LOCATION", "REGION", "SERVICE", "ENDPOINT") AS ',
'  SELECT ',
'    R.ID, ',
'    R.LOCATION, ',
'    R.IDENTIFIER REGION, ',
'    S.NAME SERVICE, ',
'    E.ENDPOINT ',
'FROM AICD_OCI_REGIONS R, AICD_OCI_SERVICES S, AICD_OCI_SERVICE_ENDPOINTS E ',
'WHERE ',
'    R.ID = E.region AND ',
'    S.ID = E.service ',
'ORDER BY 2,3',
'; '))
);
wwv_flow_imp_shared.create_install_object(
 p_id=>wwv_flow_imp.id(14468349579523421)
,p_script_id=>wwv_flow_imp.id(14468187767523420)
,p_object_owner=>'#OWNER#'
,p_object_type=>'VIEW'
,p_object_name=>'AICD_OCI_REGIONAL_ENDPOINTS'
);
end;
