'        p_chat_rest_method VARCHAR2 DEFAULT ''/20231130/actions/chat'',',
'        p_embed_rest_method VARCHAR2 DEFAULT ''/20231130/actions/embedText'',',
'        p_genai_credential VARCHAR2,',
'        p_vector_credential VARCHAR2',
'    );',
'',
'    PROCEDURE SPLIT_INTO_BLOCKS (',
'        p_media_id NUMBER,',
'        p_embed_model VARCHAR2 DEFAULT ''cohere.embed-multilingual-v3.0'',',
'        p_embed_rest_method VARCHAR2 DEFAULT ''/20231130/actions/embedText'',',
'        p_credential VARCHAR2,',
'        p_words_per_chunk NUMBER DEFAULT 800',
'    );',
'',
