'create or replace package "AICD_AISPEECH" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide integration to OCI AI Speech Service, creation & monitoring of Speech Transcription Jobs and',
'--              retrieval of the job transcript that is loaded into the AICD_MEDIA table.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Function:      CREATE_JOB',
'-- Description: Creates an AI Speech Transcribe Job and updates the AICD_MEDIA Table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_lang_code           - Language Code of the language used in the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION CREATE_JOB(',
'        n_media_id      number,',
'        vc_filename     varchar2,',
'        vc_lang_code    varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential''',
'    ) RETURN varchar2;',
'',
'-- =============================================',
'-- Function:      GET_JOB_STATUS',
'-- Description: Get status of AI Speech Transcribe Job',
'-- Parameters:',
'--      @vc_job_id              - ID of the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_STATUS(',
'        vc_job_id       varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential''',
'    ) RETURN varchar2;',
'',
'-- =============================================',
'-- Function:      GET_JOB_TRANSCRIPTION',
'-- Description: Retrieves AI Speech Transcribe Job Transcription and save it to the AICD_MEDIA table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_job_id              - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'--      @vc_obstorcred          - Credential to be used for the Object Storage service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_TRANSCRIPTION(',
'        n_media_id      number,',
'        vc_job_id       varchar2,',
'        vc_filename     varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential'',',
'        vc_obstorcred   varchar2 default ''oci_credential''',
'    ) RETURN varchar2;',
'',
'end "AICD_AISPEECH";',
'/',
'create or replace package "AICD_DBMS_VECTOR"',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide Vector Search Services, generating vectors, comparing input to data loaded the AICD_MEDIA & AICD_TRANSCRIPT_BLOCKS tables.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Procedure:      GNERATE_VECTOR',
'-- Description: Creates an AI Speech Transcribe Job and updates the AICD_MEDIA Table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_mode                - Processing mode - media: info is stored in AICD_MEDIA, block:info is stored in AICD_TRANSCRIPT_BLOCKS, NULL: Text as parameter',
'--      @c_text                 - Text as Clob',
'--      @vc_embed_model         - LLM model used to generate embeddings',
'--      @vc_vectorcred          - Credential to be used for the Vector Speech',
'-- =============================================',
'    PROCEDURE GENERATE_VECTOR(',
'        n_media_id      NUMBER,',
'        vc_mode         VARCHAR2 DEFAULT NULL,',
'        c_text          CLOB DEFAULT NULL,',
'        vc_embed_model  VARCHAR2 DEFAULT ''cohere.embed-multilingual-v3.0'',',
'        vc_vectorcred   VARCHAR2',
'    );',
'',
'end "AICD_DBMS_VECTOR";',
'/',
'create or replace package "AICD_OBJSTORAGE" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Create date: October 2024',
'-- Description: Functions supporting REST integration to OCI Object Storage Cloud Service',
'-- Global Parameters:',
'--      @      - None',
'--      ',
'-- =============================================',
'AS',
'-- Package Required Variables',
'-- Package Static Referenced Variables',
'    session_credentials         varchar2(200);',
'',
'-- =============================================',
'-- Procedure:      POST_OBJECT',
'-- Description: Posts an Object to OCI Object Storage',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @l_vc_file_name         - The name of the object stored in the APEX_APPLICATION_TEMP_FILES',
'-- Returns:                         ',
'-- =============================================',
'    procedure POST_OBJECT',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        l_vc_file_name          in varchar2 default null',
'    );',
'',
'',
'-- =============================================',
'-- Procedure:      MANAGE_OCI_BUCKETS',
'-- Description: Manage OCI Storage Buckets: LIST, CREATE, DELETE',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_compartment_ocid  - OCI Compartment OCID',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @vc_request_action      - The requested action ',
'--      @vc_session             - The current APEX session ',
'-- Returns:',
'-- Collections:',
'--                              - [APEX_SESSION]_OCI_BUCKETS_LIST',
'-- Calls:',
'-- Private functions:',
'--      REST_UTIL',
'-- =============================================',
'    PROCEDURE MANAGE_OCI_BUCKETS ',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_compartment_ocid   in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        vc_request_action       in varchar2 default null,',
'        vc_session              in varchar2 default null',
'    );',
'',
'-- =============================================',
'-- Procedure:      MANAGE_OCI_OBJECTS',
'-- Description: Manage OCI Storage Objects: LIST, CREATE, DELETE',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_compartment_ocid  - OCI Compartment OCID',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @l_vc_file_name         - The name of the object stored in the APEX_APPLICATION_TEMP_FILES',
'--      @vc_request_action      - The requested action ',
'--      @vc_session             - The current APEX session ',
'-- Returns:',
'-- Collections:',
'--                              - [APEX_SESSION]_OCI_[BUCKET]_OBJECTS_LIST',
'-- Calls:',
'-- Private functions:',
'--      REST_UTIL',
'-- =============================================',
'    PROCEDURE MANAGE_OCI_OBJECTS',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_compartment_ocid   in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        l_vc_file_name          in varchar2 default null,',
'        vc_request_action       in varchar2 default null,',
'        vc_session              in varchar2 default null',
'    );',
'',
'',
'end "AICD_OBJSTORAGE";',
'/',
'create or replace PACKAGE BODY            MEMVAULT AS',
'',
'',
'    FUNCTION GET_PARAM(',
'        p_param_name VARCHAR2',
'    ) return VARCHAR2',
'    AS',
'        l_param_value VARCHAR2(4000 CHAR);',
'    BEGIN',
'        SELECT PARAM_VALUE INTO l_param_value FROM AICD_CONFIG WHERE PARAM_NAME = p_param_name;',
'        RETURN l_param_value;',
'    END;',
'',
'    FUNCTION CREATE_SPEECH_TRANSCRIPTION_JOB(',
'        p_media_id NUMBER,',
'        p_filename VARCHAR2,',
'        p_lang_code VARCHAR2,',
'        p_credential VARCHAR2,',
'        p_request_url VARCHAR2',
'    ) RETURN VARCHAR2',
'    AS',
'        l_response  clob;',
'        l_body      clob;',
'        l_current_job_status VARCHAR2(100);',
'        l_job_id VARCHAR2(500);',
'    BEGIN',
'        SELECT',
'            JSON',
'                {',
'                ''compartmentId'' VALUE ac.compartment,',
'                ''displayName'' VALUE REPLACE(p_filename,'' '',''-''),',
'                ''inputLocation'' VALUE ',
'                {',
'                    ''locationType'' VALUE ''OBJECT_LIST_INLINE_INPUT_LOCATION'',',
'                    ''objectLocations'' VALUE [ ',
'                    {',
'                        ''bucketName'' VALUE ac.input_location,',
'                        ''namespaceName'' VALUE ac.namespace,',
'                        ''objectNames'' VALUE [p_filename]',
'                    }]',
'                },',
'                ''outputLocation'' VALUE',
'                {',
'                    ''bucketName'' VALUE ac.output_location,',
'                    ''namespaceName'' VALUE ac.namespace,',
'                    ''prefix'' VALUE ''whisper''',
'                },',
'                ''modelDetails'' VALUE',
'                {',
'                    ''languageCode'' VALUE p_lang_code,',
'                    ''modelType'' VALUE ac.model,',
'                    ''transcriptionSettings'' VALUE',
'                    {',
'                        ''diarization'' VALUE ',
'                        {',
'                            ''isDiarizationEnabled'' VALUE ''true''',
'                        }',
'                    }',
'                }',
'                }',
'        INTO l_body',
'        FROM AICD_OCI_APP_CONFIGURATION ac;',
'',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => p_request_url,',
'            p_http_method           => ''POST'',',
'            p_body                  => l_body,',
'            p_transfer_timeout      => 360,',
'            p_credential_static_id  => p_credential',
'        );',
'',
'',
'        l_job_id             := JSON_VALUE(l_response,''$.id'');',
'        l_current_job_status := JSON_VALUE(l_response,''$.lifecycleState'');',
'',
'        UPDATE AICD_MEDIA',
'        SET ',
'            PROCESS_JOB_ID  = l_job_id,',
'            PROCESS_STATUS  = ''SUBMITTED''',
'        WHERE ID = p_media_id;',
'        COMMIT;',
'',
'        RETURN l_current_job_status;',
'    END;',
'',
'',
'    FUNCTION CHECK_SPEECH_TRANSCRIPTION_JOB_STATUS(',
'        p_credential VARCHAR2,',
'        p_request_url VARCHAR2,',
'        p_job_id VARCHAR2',
'    ) RETURN VARCHAR2',
'    AS',
'        l_response  clob;',
'        l_body      clob;',
'        l_current_job_status VARCHAR2(100);',
'    BEGIN',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => p_request_url || ''/'' || p_job_id,',
'            p_http_method           => ''GET'',',
'            p_credential_static_id  => p_credential',
'        );',
'',
'',
'        APEX_DEBUG.INFO(''Current Job ID %s'', p_job_id);',
'        l_current_job_status := JSON_VALUE(l_response,''$.lifecycleState'');',
'        RETURN l_current_job_status;',
'    END;',
'',
'',
'',
'    PROCEDURE SAVE_MEDIA_TRANSCRIPT(',
'        p_media_id NUMBER,',
'        p_credential VARCHAR2,',
'        p_filename VARCHAR2',
'    ) AS',
'        l_response      clob;',
'        l_request_url   varchar2(32767);',
'        l_filename      varchar2(255) := p_filename || ''.json'';',
'        l_transcription blob;',
'    BEGIN',
'        SELECT ',
'            E.ENDPOINT || ''/n/'' || AC.NAMESPACE || ''/b/'' || AC.OUTPUT_LOCATION || ''/o/'' || replace(apex_util.url_encode(JSON_VALUE(l_response,''$.outputLocation.prefix'') || AC.NAMESPACE || ''_'' || AC.INPUT_LOCATION || ''_'' || l_filename || ''.json''),''+'','
||'''%20'')',
'        INTO l_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''os'';',
'',
'        APEX_DEBUG.INFO(''Requested: %s'',l_request_url);',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        -- may need to save this to a table to be able to parse correctly.',
'        l_transcription := apex_web_service.make_rest_request_b(',
'            p_url => l_request_url,',
'            p_http_method => ''GET'',',
'            p_credential_static_id => p_credential',
'        );',
'',
'',
'',
'        UPDATE AICD_MEDIA',
'        SET ',
'            TRANJSON = l_transcription,',
'            TRANSCRIPT = (',
'                SELECT jt.transcript',
'                FROM JSON_TABLE (',
'                    l_transcription, ''$.transcriptions[0]''',
'                    NULL ON EMPTY',
'                    COLUMNS',
'                    (',
'                        transcript      clob    path ''$.transcription''',
'                    )',
'                ) jt ',
'            )',
'',
'        WHERE',
'            ID = p_media_id;',
'',
'        COMMIT;',
'    END;',
'',
'',
'',
'    PROCEDURE GENERATE_SUMMARY_VECTOR(',
'        p_media_id NUMBER,',
'        p_chat_model VARCHAR2 DEFAULT ''meta.llama-3.3-70b-instruct'',',
'        p_embed_model VARCHAR2 DEFAULT ''cohere.embed-multilingual-v3.0'',',
'        p_system_prompt VARCHAR2 DEFAULT ''You are an expert in reviewing audio text on cloud, software, and hardware technology topics. You will provide a json response with a summary element and a comma separated list of the top 25 technology terms '
||'used in the tags element. If no technology terms are used provide an empty tags element. Provide the response on a single line without any explanation.'',',
'        p_max_tokens NUMBER DEFAULT 600,',
'        p_temperature NUMBER DEFAULT 1,',
'        p_chat_rest_method VARCHAR2 DEFAULT ''/20231130/actions/chat'',',
'        p_embed_rest_method VARCHAR2 DEFAULT ''/20231130/actions/embedText'',',
'        p_genai_credential VARCHAR2,',
'        p_vector_credential VARCHAR2',
'    ) AS',
'        l_transcript    clob;',
'        l_prompt        clob;',
'        l_messages      apex_ai.t_chat_messages := apex_ai.c_chat_messages;',
'        l_response      clob;',
'        l_request_url   varchar2(32767);',
'        l_body          clob; ',
'        l_body_b        clob; ',
'        l_body_s        clob; ',
'        l_body_t        clob; ',
'        l_summary       clob;',
'        l_tags          clob; ',
'        --l_vector_b      clob; ',
'        l_vector_s      clob; ',
'        l_vector_t      clob;',
'        l_embe_b        json_array_t;',
'    BEGIN',
'',
'',
'        SELECT TRANSCRIPT INTO l_transcript',
'            FROM AICD_MEDIA',
'            WHERE ID = p_media_id;',
'',
'        -- Get the Chat AI Endpoint',
'        SELECT ',
'            E.ENDPOINT || p_chat_rest_method',
'        INTO l_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''generative-ai-inference'';',
'',
'        APEX_DEBUG.INFO(''Current url is %s'', l_request_url);',
'',
'',
'        select json_object(',
'            ''compartmentId'' value ac.compartment,',
'            ''servingMode''   value json_object (',
'                ''modelId''       value p_chat_model,',
'                ''servingType''   value ''ON_DEMAND''',
'            ),',
'            ''chatRequest''   value json_object(',
'                ''messages''  value json_array( ',
'                    json_object(',
'                        ''role''      value ''SYSTEM'',',
'                        ''content''   value json_array (',
'                            json_object(',
'                                ''type''      value ''TEXT'',',
'                                ''text''      value p_system_prompt',
'                            )',
'                        )',
'                    ),',
'                    json_object(',
'                        ''role''      value ''USER'',',
'                        ''content''   value json_array (',
'                            json_object(',
'                                ''type''      value ''TEXT'',',
'                                ''text''      value l_transcript',
'                            )',
'                        ) RETURNING CLOB',
'                    ) RETURNING CLOB',
'                ) ,',
'                ''apiFormat''         value ''GENERIC'',',
'                ''maxTokens''         value p_max_tokens,',
'                ''isStream''          value false,',
'                ''numGenerations''    value 1,',
'                ''frequencyPenalty''  value 0,',
'                ''presencePenalty''   value 0,',
'                ''temperature''       value p_temperature,',
'                ''topP''              value 1.0,',
'                ''topK''              value 1',
'            ) RETURNING CLOB',
'        ) ',
'        INTO l_body',
'        from AICD_OCI_APP_CONFIGURATION AC;',
'',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        APEX_DEBUG.INFO(''Get GenAI Summary and Tags'');',
'        l_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => l_request_url ,',
'            p_http_method           => ''POST'',',
'            p_body                  => l_body,',
'            p_credential_static_id  => p_genai_credential',
'        );',
'',
'        l_response  := replace(replace(replace(l_response,''\'',''''),''":"{"'',''":{"''),''""}"'',''""}'');',
'        --APEX_DEBUG.INFO(l_response);',
'        l_summary   := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.summary'');',
'        l_tags      := json_value(l_response,''$.chatResponse.choices[0].message.content[0].text.tags'');',
'',
'',
'',
'        -- Get the Embeddings AI Endpoint',
'        SELECT ',
'            E.ENDPOINT || p_embed_rest_method',
'        INTO l_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''generative-ai-inference'';',
'',
'        APEX_DEBUG.INFO(''Current url is %s'', l_request_url);   ',
'        --Need to loop once for the text block, the summary, and the tags',
'',
'',
'        UPDATE AICD_MEDIA',
'        SET',
'            TAGS            = l_tags,',
'            VECTOR_TAGS     = ',
'                dbms_vector_chain.utl_to_embedding(',
'                    l_tags,',
'                    json(''{',
'                    "provider": "ocigenai",',
'                    "credential_name": "''|| p_vector_credential || ''",',
'                    "url": "''||l_request_url||''",',
'                    "model": "''||p_embed_model||''"',
'                    }'')),',
'            SUMMARY         = l_summary,',
'            VECTOR_SUMMARY  = ',
'                dbms_vector_chain.utl_to_embedding(',
'                    l_summary,',
'                    json(''{',
'                    "provider": "ocigenai",',
'                    "credential_name": "''|| p_vector_credential || ''",',
'                    "url": "''||l_request_url||''",',
'                    "model": "''||p_embed_model||''"',
'                    }''))',
'        WHERE',
'            ID = p_media_id;',
'',
'        commit;',
'',
'    END;',
'',
'',
'',
'    PROCEDURE SPLIT_INTO_BLOCKS (',
'        p_media_id NUMBER,',
'        p_embed_model VARCHAR2 DEFAULT ''cohere.embed-multilingual-v3.0'',',
'        p_embed_rest_method VARCHAR2 DEFAULT ''/20231130/actions/embedText'',',
'        p_credential VARCHAR2,',
'        p_words_per_chunk NUMBER DEFAULT 800',
'    )',
'    AS',
'        l_request_url   varchar2(32767);',
'    BEGIN',
'        -- Get the Chat AI Endpoint',
'        SELECT ',
'            E.ENDPOINT || p_embed_rest_method',
'        INTO l_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''generative-ai-inference'';',
'',
'',
'',
'',
'        INSERT INTO aicd_transcript_blocks (',
'            media_id,',
'            speaker_indx,',
'            block,',
'            start_order,',
'            end_order,',
'            vector_block',
'        )',
'        with tokens as (',
'            SELECT jt.token, to_number(replace(jt.startTime,''s'')) startTime, to_number(replace(jt.endTime,''s'')) endTime, jt.speakerIndex, rownum token_id, ',
'                ROW_NUMBER() OVER (ORDER BY rownum) -',
'                ROW_NUMBER() OVER (PARTITION BY speakerIndex ORDER BY rownum) AS group_id',
'                FROM AICD_MEDIA M, JSON_TABLE (',
'                        m.tranjson, ''$.transcriptions[0].tokens[*]''',
'                        NULL ON EMPTY',
'                        COLUMNS (',
'                            token           varchar2(4000)  path ''$.token'',',
'                            startTime       varchar2(4000)  path ''$.startTime'',',
'                            endTime         varchar2(4000)  path ''$.endTime'',',
'                            confidence      number  path ''$.confidence'',',
'                            speakerIndex    int     path ''$.speakerIndex''',
'                        )',
'                    ) jt ',
'                    WHERE ',
'                        m.ID = p_media_id',
'                    ORDER BY rownum',
'',
'        ),',
'        T as (',
'            SELECT ',
'                listagg(token,'' '') WITHIN GROUP (ORDER BY token_id) as block,',
'                t.speakerIndex,',
'                min(startTime) as groupStartTime,',
'                max(endTime) as groupEndTime',
'            FROM',
'                tokens t',
'            GROUP BY group_id,speakerIndex',
'            ORDER BY groupStartTime',
'        ) ',
'        SELECT ',
'            p_media_id MEDIA_ID,',
'            T.SPEAKERINDEX,',
'            JSON_VALUE(C.column_value, ''$.chunk_data'') AS chunked_block,',
'            T.GROUPSTARTTIME,',
'            T.GROUPENDTIME,',
'            dbms_vector_chain.utl_to_embedding(',
'                JSON_VALUE(C.column_value, ''$.chunk_data''),',
'                  json(''{',
'                  "provider": "ocigenai",',
'                  "credential_name": "''|| p_credential || ''",',
'                  "url": "''||l_request_url||''",',
'                  "model": "''||p_embed_model||''"',
'                }'')) embedding',
'            FROM T,',
'            dbms_vector_chain.utl_to_chunks(',
'                T.block, ',
'                json(''{"by":"words","max":"''|| p_words_per_chunk || ''","split":"sentence","normalize":"all"}'')',
'            ) C;',
'',
'',
'            commit;',
'',
'    END;',
'',
'',
'',
'',
'    FUNCTION ASK_QUESTION (question varchar2,',
'        p_credential VARCHAR2,',
'        p_endpoint VARCHAR2,',
'        p_model VARCHAR2',
'    )RETURN VARCHAR2 as',
'        v_combined_result VARCHAR2(32000) := '''';',
'        v_json_result     VARCHAR2(32000);',
'        v_temp     VARCHAR2(32000);',
'    BEGIN',
'',
'        FOR rec IN (SELECT speech',
'        FROM transcripts',
'        ORDER BY VECTOR_DISTANCE( SPEECH_VECTOR, to_vector((select embed_vector',
'        from dbms_vector.UTL_TO_EMBEDDINGS(question,',
'        json(''{',
'                "provider": "ocigenai",',
'                "credential_name": "'' || p_credential ||''",',
'                "url": "''|| p_endpoint ||''",',
'                "model": "''|| p_model ||''"',
'                }'') ),',
'        JSON_TABLE(column_value, ''$[*]'' COLUMNS (embed_id NUMBER PATH ''$.embed_id'', embed_data VARCHAR2(4000) PATH ''$.embed_data'', ',
'            embed_vector CLOB PATH ''$.embed_vector'')) et)), DOT )',
'        FETCH APPROXIMATE FIRST 5 ROWS ONLY) LOOP',
'',
'            v_temp := rec.speech;',
'',
'            IF v_combined_result IS NOT NULL THEN',
'                v_combined_result := v_combined_result || '', '';',
'            END IF;',
'',
'            v_combined_result := v_combined_'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(14468723189526766)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'result || v_temp;',
'        END LOOP;',
'',
'      --  DBMS_OUTPUT.PUT_LINE(''Combined Result: '' || v_combined_result);',
'        v_json_result := json_object(',
'            ''question'' VALUE question,',
'            ''answer'' VALUE v_combined_result RETURNING VARCHAR2(32000)',
'        );',
'',
'        RETURN v_json_result;',
'    end;',
'',
'    PROCEDURE ADD_CHAT_CONTEXT(p_question IN VARCHAR2, p_answer IN VARCHAR2) AS ',
'    BEGIN',
'        -- Insert new question',
'        INSERT INTO CHAT_HISTORY (USER_ID, QUESTION, ANSWER) VALUES (SYS_CONTEXT(''USERENV'', ''SESSION_USER''), p_question, p_answer);',
'',
'        -- only last 5 messages',
'       DELETE FROM CHAT_HISTORY',
'        WHERE CHAT_ID NOT IN (',
'        SELECT CHAT_ID FROM (',
'            SELECT CHAT_ID FROM CHAT_HISTORY',
'            ORDER BY TIMESTAMP DESC',
'        ) WHERE ROWNUM <= 5',
'    );',
'',
'        COMMIT;',
'    END;',
'',
'    FUNCTION GET_CHAT_RESPONSE(p_new_question IN VARCHAR2,',
'    p_credential VARCHAR2,',
'    p_endpoint VARCHAR2,',
'    p_model VARCHAR2,',
'    p_endpoint_gen_text VARCHAR2,',
'    p_model_gen_text VARCHAR2) ',
'    RETURN VARCHAR2 AS ',
'        v_context CLOB;',
'        v_response VARCHAR2(32000);',
'        v_final_response VARCHAR2(32000);',
'    BEGIN',
'',
'        -- Get the last 5 messages as context',
'        SELECT LISTAGG(QUESTION, '' '') WITHIN GROUP (ORDER BY TIMESTAMP ASC) ',
'        INTO v_context',
'        FROM CHAT_HISTORY;',
'',
'        DBMS_OUTPUT.PUT_LINE(''v_context  : '' || v_context);',
'',
'',
'        RETURN v_final_response;',
'    END;',
'',
'    FUNCTION GENERATE_TEXT (question varchar2,',
'        p_credential VARCHAR2,',
'        p_endpoint_gen_text VARCHAR2,',
'        p_model_gen_text VARCHAR2',
'    )',
'    RETURN VARCHAR2 AS ',
'    v_final_response VARCHAR2(32000);',
'    v_answer_json VARCHAR2(32000);',
'    v_question_json VARCHAR2(32000);',
'    v_context CLOB;',
'    BEGIN',
'          SELECT jt.answer_text, jt.question_text into v_answer_json , v_question_json',
'                FROM JSON_TABLE(',
'                    question,',
'                    ''$'' COLUMNS (',
'                question_text VARCHAR2(4000) PATH ''$.question'',',
'                answer_text  VARCHAR2(4000) PATH ''$.answer''  ',
'                ) ) jt;',
'      --.  ',
'     -- DBMS_OUTPUT.PUT_LINE(''v_answer_json: '' || v_answer_json);',
'     SELECT LISTAGG(''Question: '' || QUESTION || '' Answer: '' || ANSWER, '' '') WITHIN GROUP (ORDER BY TIMESTAMP ASC) ',
'        INTO v_context',
'    FROM CHAT_HISTORY;',
'',
'       -- DBMS_OUTPUT.PUT_LINE(''v_context  : '' || v_context);',
'        if v_context is null then',
'            select dbms_vector_chain.utl_to_generate_text(',
'             ''You are an AI-powered chatbot that generates professional responses. You retrieve the most ',
'             accurate and relevant information from a database to provide high-quality answers. Do not include titles or references to this prompt in your response. ',
'             Ensure that your responses are clear, well-structured, and professional. This is the last question: '' || v_question_json || ''',
'            These are the answers retrieved from the database: '' || v_answer_json || ''',
'            If these answers do not make sense, please improve them.'',',
'             json(''{ "provider": "ocigenai",',
'                        "credential_name": "'' || p_credential ||''",',
'                        "url": "''|| p_endpoint_gen_text ||''",',
'                        "model": "''|| p_model_gen_text ||''"',
'                        }'')',
'                ) into v_final_response',
'                FROM dual;',
'',
'        else',
'            select dbms_vector_chain.utl_to_generate_text(',
'             ''You are an AI-powered chatbot that generates professional responses by considering previous questions and answers for context. Do not respond to previous questions; they are provided solely for context. Retrieve the most accurate and re'
||'levant information from the database to provide high-quality answers. ',
'             Do not include titles or references to this prompt in your response. Ensure your responses are clear, well-structured, and professional.',
'            This is the last question: '' || v_question_json || ''',
'            These are the answers retrieved from the database: '' || v_answer_json || ''',
'            If these answers do not make sense, please improve them.',
'            These are the previous questions and answers: '' || v_context,',
'             json(''{ "provider": "ocigenai",',
'                        "credential_name": "'' || p_credential ||''",',
'                        "url": "''|| p_endpoint_gen_text ||''",',
'                        "model": "''|| p_model_gen_text ||''"',
'                        }'')',
'                ) into v_final_response',
'                FROM dual;',
'',
'        end if;',
'         -- Add the new question to chat history',
'        ADD_CHAT_CONTEXT(v_question_json, v_final_response);',
'',
'        return v_final_response;',
'',
'    END;',
'',
'',
'END MEMVAULT;',
'/',
'create or replace PACKAGE BODY MEETING_VAULT AS',
'',
'FUNCTION SPEECHAI_TRANSCRIPTION (',
'    p_credential VARCHAR2,',
'    p_endpoint VARCHAR2,',
'    p_compartment_ocid VARCHAR2,',
'    p_namespaceName VARCHAR2,',
'    p_bucketName VARCHAR2,',
'    p_outputbucketName VARCHAR2,',
'    p_objectName VARCHAR2',
')  RETURN VARCHAR2  AS',
'    resp DBMS_CLOUD_TYPES.resp;',
'    json_response CLOB;',
'    v_textfromai VARCHAR2(32767);',
'  BEGIN',
'    resp := DBMS_CLOUD.send_request(',
'        credential_name => p_credential,',
'        uri => p_endpoint,',
'        method => ''POST'',',
'        body => UTL_RAW.cast_to_raw(',
'            json_object(',
'              ''compartmentId'' value p_compartment_ocid,',
'                ''displayName'' VALUE ''whisper_''||p_objectName,',
'              ''inputLocation'' value json_object(',
'                ''locationType'' value ''OBJECT_LIST_INLINE_INPUT_LOCATION'',',
'                ''objectLocations'' value json_array(',
'                  json_object(',
'                    ''bucketName'' value p_bucketName,',
'                    ''namespaceName'' value p_namespaceName,',
'                    ''objectNames'' value json_array(p_objectName)',
'                  )',
'                )',
'              ),',
'              ''outputLocation'' value json_object(',
'                ''bucketName'' value p_outputbucketName,',
'                ''namespaceName'' value p_namespaceName  ,',
'                ''prefix'' value ''whisper''',
'              ),',
'              ''modelDetails'' value json_object(',
'                ''languageCode'' value ''en'',',
'                ''modelType'' value ''WHISPER_MEDIUM'',',
'                ''transcriptionSettings'' value json_object(',
'                    ''diarization'' value  json_object(',
'                        ''isDiarizationEnabled'' value ''true''',
'                    )',
'              )',
'            )',
'        )',
'    ));',
'    json_response := DBMS_CLOUD.get_response_text(resp);',
'    RETURN JSON_OBJECT_T.parse(json_response).get_string(''id'');',
'    ',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'        RAISE;',
'END SPEECHAI_TRANSCRIPTION;',
'',
'',
'',
'PROCEDURE CREATE_ERROR_TABLE (',
'  l_DML_TABLE_NAME       DBMS_QUOTED_ID,',
'  l_ERR_LOG_TABLE_NAME   DBMS_QUOTED_ID,',
'  l_SKIP_UNSUPPORTED     BOOLEAN,',
'  l_SCHEMA_NAME          DBMS_QUOTED_ID',
') IS',
'  TABLE_EXISTS           EXCEPTION;',
'  PRAGMA                 EXCEPTION_INIT(TABLE_EXISTS, -955);',
'BEGIN',
'  "SYS"."DBMS_ERRLOG"."CREATE_ERROR_LOG"',
'  ( DML_TABLE_NAME       => l_DML_TABLE_NAME',
'   ,ERR_LOG_TABLE_NAME   => l_ERR_LOG_TABLE_NAME',
'   ,SKIP_UNSUPPORTED     => l_SKIP_UNSUPPORTED',
'   ,ERR_LOG_TABLE_OWNER  => l_SCHEMA_NAME',
'  );',
'EXCEPTION WHEN TABLE_EXISTS THEN',
'  SYS.DBMS_OUTPUT.PUT_LINE(''DML error log table already exists.'');',
'END;',
'',
'',
'PROCEDURE LOAD_MEETING_FILE(',
'  l_OWNER                 DBMS_QUOTED_ID,',
'  l_SCHEMA                DBMS_QUOTED_ID,',
'  l_CREDENTIAL_NAME       DBMS_QUOTED_ID,',
'  prefix varchar2',
') IS',
'  l_FORMAT                CLOB :=',
'    ''{',
'       "unpackarrays" : "true",',
'       "ignoreblanklines" : "true",',
'       "rejectlimit" : "unlimited",',
'       "maxdocsize" : 33554432,',
'       "characterset" : "AL32UTF8",',
'       "recorddelimiter" : "0x''''01''''"',
'     }'';',
'',
'  --prefix varchar2(200) := ''job-amaaaaaa2t2mwsaakhnwkl47ajo4nk4e6tqf62xse2ohtqvhz6w5ema7ntma/idprle0k7dv3_audio_files_test_meeting_vault.wav.json'';',
'  file_name varchar2(100) := SUBSTR(prefix, INSTR(prefix, ''/'', -1) + 1);',
'',
'  l_FILE_URI_LIST         CLOB :=',
'  --q''[''https://objectstorage.us-chicago-1.oraclecloud.com/n/idprle0k7dv3/b/transcripts/o/whisper/job-amaaaaaa2t2mwsaascebxn4wulsydp3noyc7kwti53mlsc3ckdvsudovx74a/idprle0k7dv3_audio_files_test_meeting_vault.wav.json'']'';',
'    ''https://objectstorage.us-chicago-1.oraclecloud.com/n/idprle0k7dv3/b/transcripts/o/whisper/'' || prefix;',
'',
'  ',
'  l_COLNAME_LIST          CLOB :=',
'    q''[',
'    "FILE_NAME"',
'    ,"STATUS"',
'    ,"TIMECREATED"',
'    ,"MODELDETAILS"',
'    ,"TRANSCRIPTIONS"',
'    ,"AUDIOFORMATDETAILS"]'';',
'',
'  l_COLLECTION_NAME       DBMS_ID := ''TEMP_COLLECTION_SPEECH_JOBS'';',
'  l_COLLECTION_NAME_EQN   DBMS_QUOTED_ID := ''"TEMP_COLLECTION_SPEECH_JOBS"'';',
'  l_VIEW_NAME             DBMS_ID := ''"TEMP_VIEW_SPEECH_JOBS"'';',
'  l_TABLE_NAME            DBMS_QUOTED_ID := ''"SPEECH_JOBS"'';',
'  l_TABLE_NAME_SQN        DBMS_ID := ''SPEECH_JOBS'';',
'  l_LOGERR_CLAUSE         CLOB :=',
'    q''[ LOG ERRORS INTO "AI_MEETING"."ERROR_TABLE_SPEECH_JOB" ( ''INGEST_DML_193_1'' ) REJECT LIMIT 10000000 ]'';',
'',
'  l_OPERATION_ID          NUMBER;',
'  l_CUR_COLLECTION        SYS.SODA_COLLECTION_T := null;',
'',
'  l_STATUS                NUMBER;',
'  l_SQL_STMT              CLOB;',
'  l_VIEW_CREATED          BOOLEAN := false;',
'',
'BEGIN',
'',
' l_SQL_STMT := ''CREATE JSON COLLECTION TABLE '' || l_OWNER || ''.'' ||',
'    l_COLLECTION_NAME_EQN;',
'  execute immediate l_SQL_STMT;',
'',
'  C##CLOUD$SERVICE.DBMS_CLOUD.COPY_COLLECTION',
'  ( COLLECTION_NAME     =>   l_COLLECTION_NAME',
'   ,CREDENTIAL_NAME     =>   l_CREDENTIAL_NAME',
'   ,FILE_URI_LIST       =>   l_FILE_URI_LIST',
'   ,FORMAT              =>   l_FORMAT',
'   ,OPERATION_ID        =>   l_OPERATION_ID',
'  );',
'',
'  l_CUR_COLLECTION := SYS.DBMS_SODA.OPEN_COLLECTION(l_COLLECTION_NAME);',
'',
'l_SQL_STMT := ''CREATE OR REPLACE VIEW '' || l_OWNER || ''.'' || l_VIEW_NAME ||',
'     ''  AS SELECT   '' || ''''''''|| file_name || '''''''' || ''AS FILE_NAME ',
'     ,"STATUS" AS "STATUS"',
'    ,"TIMECREATED" AS "TIMECREATED"',
'    ,"MODELDETAILS" AS "MODELDETAILS"',
'    ,"TRANSCRIPTIONS" AS "TRANSCRIPTIONS"',
'    ,"AUDIOFORMATDETAILS" AS "AUDIOFORMATDETAILS"',
'    FROM (SELECT JT.* FROM '' || l_OWNER || ''.'' || l_COLLECTION_NAME ||',
'    '' RT, JSON_TABLE("DATA", ''''$[*]'''' COLUMNS ',
'    "STATUS" VARCHAR2(32767)  path ''''$.status''''',
'    ,"TIMECREATED" VARCHAR2(32767)  path ''''$.timeCreated''''',
'    ,"MODELDETAILS" json  path ''''$.modelDetails''''',
'    ,"TRANSCRIPTIONS" json  path ''''$.transcriptions''''',
'    ,"AUDIOFORMATDETAILS" json  path ''''$.audioFormatDetails'''')JT)'';',
'',
' DBMS_OUTPUT.PUT_LINE(l_SQL_STMT);',
'  EXECUTE IMMEDIATE l_SQL_STMT;',
'',
'  l_VIEW_CREATED := true;',
'',
'  -- Insert into the target table, including the FILE_NAME column',
'  l_SQL_STMT :=',
'    ''INSERT INTO '' || l_SCHEMA || ''.'' || l_TABLE_NAME || ''('' || l_COLNAME_LIST || '') '' ||',
'    ''SELECT * FROM '' || l_OWNER || ''.'' || l_VIEW_NAME || '' '' || l_LOGERR_CLAUSE;',
'',
'  EXECUTE IMMEDIATE l_SQL_STMT;',
'',
'  -- Drop the view after insertion',
'  l_SQL_STMT := ''DROP VIEW '' || l_OWNER || ''.'' || l_VIEW_NAME;',
' -- EXECUTE IMMEDIATE l_SQL_STMT;',
'',
' l_STATUS := SYS.DBMS_SODA.DROP_COLLECTION(l_COLLECTION_NAME, TRUE, TRUE);',
'',
'  COMMIT;',
'',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    IF l_CUR_COLLECTION IS NOT NULL THEN',
'      l_STATUS := SYS.DBMS_SODA.DROP_COLLECTION(l_COLLECTION_NAME, TRUE, TRUE);',
'    END IF;',
'',
'    IF l_VIEW_CREATED THEN',
'      l_SQL_STMT := ''DROP VIEW '' || l_OWNER || ''.'' || l_VIEW_NAME;',
'      --EXECUTE IMMEDIATE l_SQL_STMT;',
'    END IF;',
'',
'    ROLLBACK;',
'    RAISE;',
' ',
'END;',
'',
'PROCEDURE LOAD_TRANSCRIPTS_PROCESSED(FILE_NAME varchar2',
') is',
'BEGIN',
'',
'insert into transcript_processed',
'SELECT ',
'FILE_ID,',
'FILE_NAME,',
'speakerindex SPEAKERINDEX,',
'aggregated_speech AGGREGATED_SPEECH,',
'start_order START_ORDER,',
'end_order END_ORDER FROM (',
'WITH wf as (    ',
'SELECT',
'    w.FILE_ID,',
'    w.FILE_NAME,',
'    jt_w.token,',
'    jt_w.speakerIndex,',
'    jt_w.confidence,',
'    ROWNUM token_order',
'  --  jt_w.*',
'FROM',
'    (Select * from AI_MEETING.SPEECH_JOBS where FILE_NAME = FILE_NAME) w,',
'    JSON_TABLE(transcriptions, ''$[0].tokens[*]''',
'        COLUMNS (',
'            token VARCHAR2(200) PATH ''$.token'',',
'            speakerIndex VARCHAR2(10) PATH ''$.speakerIndex'',',
'            confidence VARCHAR2(10) PATH ''$.confidence''',
'        )) jt_w',
'),',
'',
'joined as (',
'    SELECT wf.FILE_ID, wf.FILE_NAME, wf.speakerIndex, wf.token, --CASE WHEN wf.confidence < 0.8 THEN wf.confidence ELSE '' '' END confidence, ',
'    token_order',
'        FROM wf',
'        ORDER BY token_order',
')',
',ranked_speakers AS (',
'  SELECT FILE_ID, FILE_NAME,',
'    speakerIndex,',
'    token,',
'    token_order,',
'    ROW_NUMBER() OVER (PARTITION BY speakerIndex ORDER BY token_order) AS speaker_rn',
'  FROM ',
'    joined',
'),',
'speaker_groups AS (',
'  SELECT FILE_ID, FILE_NAME,',
'    speakerIndex,',
'    token,',
'    token_order,',
'    token_order - speaker_rn AS group_id',
'  FROM ',
'    ranked_speakers',
')',
'SELECT FILE_ID, FILE_NAME,',
'  speakerIndex,',
'  LISTAGG(token, '' '') WITHIN GROUP (ORDER BY token_order) AS aggregated_speech,',
'  MIN(token_order) AS start_order,',
'  MAX(token_order) AS end_order',
'FROM ',
'  speaker_groups',
'GROUP BY ',
'  speakerIndex, group_id, FILE_ID, FILE_NAME',
'ORDER BY ',
'  MIN(token_order));',
'',
'END LOAD_TRANSCRIPTS_PROCESSED;',
'',
'',
'PROCEDURE LOAD_TRANSCRIPTS(FILE_NAME varchar2',
') IS',
'BEGIN',
'insert into AI_MEETING.transcripts',
'select FILE_ID, SPEAKERINDEX, 2,'''' as speaker_name,aggregated_speech, start_order, end_order, ',
'dbms_vector_chain.utl_to_embedding(',
'            ''SPEAKER: '' || SPEAKERINDEX || '': '' || substr(AGGREGATED_SPEECH,1,200),',
'              json(''{',
'              "provider": "ocigenai",',
'              "credential_name": "OCI_CRED",',
'              "url": "https://inference.generativeai.us-chicago-1.oci.oraclecloud.com/20231130/actions/embedText",',
'              "model": "cohere.embed-english-v3.0"',
'            }'')) from AI_MEETING.TRANSCRIPT_PROCESSED;',
'END LOAD_TRANSCRIPTS;',
'',
'PROCEDURE SPEECHAI_STATUS (',
'    p_credential VARCHAR2,',
'    p_endpoint VARCHAR2,',
'    p_compartment_ocid VARCHAR2,',
'    p_job_ocid VARCHAR2,',
'    p_status OUT VARCHAR2,',
'    p_prefix OUT VARCHAR2',
')   IS',
'    resp DBMS_CLOUD_TYPES.resp;',
'    json_response CLOB;',
'    json_response_obj JSON_OBJECT_T;',
'BEGIN',
'    resp := DBMS_CLOUD.send_request(',
'        credential_name => ''OCI_CRED'',',
'        uri => p_endpoint||''/''||p_job_ocid||''?compartmentId=''||p_compartment_ocid,',
'        method => ''GET'');',
'    json_response := DBMS_CLOUD.get_response_text(resp);',
'    json_response_obj := JSON_OBJECT_T.parse(json_response);',
'    p_status := json_response_obj.get_string(''lifecycleState'');',
'    p_prefix := json_object_t(json_response_obj.get(''outputLocation'')).get_string(''prefix'');',
'    ',
'',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'        RAISE;',
'END SPEECHAI_STATUS;',
'',
'',
'PROCEDURE SPEECHAI_WAIT_COMPLETION (',
'    p_credential VARCHAR2,',
'    p_endpoint VARCHAR2,',
'    p_compartment_ocid VARCHAR2,',
'    p_job_ocid VARCHAR2,',
'    p_freq NUMBER,',
'    p_timeout NUMBER,',
'    p_status OUT VARCHAR2,',
'    p_prefix OUT VARCHAR2',
') IS',
'    l_cnt number := 0;',
'BEGIN',
'    p_status := '' '';',
'    ',
'           WHILE p_status NOT IN (''SUCCEEDED'',''FAILED'',''CANCELING'',''CANCELED'') AND l_cnt < (p_timeout / p_freq)LOOP',
'                DBMS_SESSION.SLEEP(p_freq);                ',
'                SPEECHAI_STATUS(p_credential,',
'                   p_endpoint,',
'                   p_compartment_ocid,',
'                   p_job_ocid,',
'                   p_status,',
'                   p_prefix);',
'                l_cnt := l_cnt+1;',
'           END LOOP;',
'    ',
'',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'        RAISE;',
'END SPEECHAI_WAIT_COMPLETION;',
'',
'FUNCTION ASK_QUESTION (question varchar2,',
'    p_credential VARCHAR2,',
'    p_endpoint VARCHAR2,',
'    p_model VARCHAR2',
')RETURN VARCHAR2 as',
'    v_combined_result VARCHAR2(32000) := '''';',
'    v_json_result     VARCHAR2(32000);',
'    v_temp     VARCHAR2(32000);',
'BEGIN',
'',
'    FOR rec IN (SELECT speech',
'    FROM transcripts',
'    ORDER BY VECTOR_DISTANCE( SPEECH_VECTOR, to_vector((select embed_vector',
'    from dbms_vector.UTL_TO_EMBEDDINGS(question,',
'    json(''{',
'            "provider": "ocigenai",',
'            "credential_name": "'' || p_credential ||''",',
'            "url": "''|| p_endpoint ||''",',
'            "model": "''|| p_model ||''"',
'            }'') ),',
'    JSON_TABLE(column_value, ''$[*]'' COLUMNS (embed_id NUMBER PATH ''$.embed_id'', embed_data VARCHAR2(4000) PATH ''$.embed_data'', ',
'        embed_vector CLOB PATH ''$.embed_vector'')) et)), DOT )',
'    FETCH APPROXIMATE FIRST 5 ROWS ONLY) LOOP',
'',
'        v_temp := rec.speech;',
'        ',
'        IF v_combined_result IS NOT NULL THEN',
'            v_combined_result := v_combined_result || '', '';',
'        END IF;',
'',
'        v_combined_result := v_combined_result || v_temp;',
'    END LOOP;',
'',
'  --  DBMS_OUTPUT.PUT_LINE(''Combined Result: '' || v_combined_result);',
'    v_json_result := json_object(',
'        ''question'' VALUE question,',
'        ''answer'' VALUE v_combined_result RETURNING VARCHAR2(32000)',
'    );',
'',
'    RETURN v_json_result;',
'end;',
'',
'PROCEDURE ADD_CHAT_CONTEXT(p_question IN VARCHAR2, p_answer IN VARCHAR2) AS ',
'BEGIN',
'    -- Insert new question',
'    INSERT INTO CHAT_HISTORY (USER_ID, QUESTION, ANSWER) VALUES (SYS_CONTEXT(''USERENV'', ''SESSION_USER''), p_question, p_answer);',
'',
'    -- only last 5 messages',
'   DELETE FROM CHAT_HISTORY',
'    WHERE CHAT_ID NOT IN (',
'    SELECT CHAT_ID FROM (',
'        SELECT CHAT_ID FROM CHAT_HISTORY',
'        ORDER BY TIMESTAMP DESC',
'    ) WHERE ROWNUM <= 5',
');',
'',
'    COMMIT;',
'END;',
'',
'FUNCTION GET_CHAT_RESPONSE(p_new_question IN VARCHAR2,',
'p_credential VARCHAR2,',
'p_endpoint VARCHAR2,',
'p_model VARCHAR2,',
'p_endpoint_gen_text VARCHAR2,',
'p_model_gen_text VARCHAR2) ',
'RETURN VARCHAR2 AS ',
'    v_context CLOB;',
'    v_response VARCHAR2(32000);',
'    v_final_response VARCHAR2(32000);',
'BEGIN',
'   ',
'    -- Get the last 5 messages as context',
'    SELECT LISTAGG(QUESTION, '' '') WITHIN GROUP (ORDER BY TIMESTAMP ASC) ',
'    INTO v_context',
'    FROM CHAT_HISTORY;',
'    ',
'    DBMS_OUTPUT.PUT_LINE(''v_context  : '' || v_context);',
'    ',
'    ',
'    RETURN v_final_response;',
'END;',
'',
'FUNCTION GENERATE_TEXT (question varchar2,',
'    p_credential VARCHAR2,',
'    p_endpoint_gen_text VARCHAR2,',
'    p_model_gen_text VARCHAR2',
')',
'RETURN VARCHAR2 AS ',
'v_final_response VARCHAR2(32000);',
'v_answer_json VARCHAR2(32000);',
'v_question_json VARCHAR2(32000);',
'v_context CLOB;',
'BEGIN',
'      SELECT jt.answer_text, jt.question_text into v_answer_json , v_question_json',
'            FROM JSON_TABLE(',
'                question,',
'                ''$'' COLUMNS (',
'            question_text VARCHAR2(4000) PATH ''$.question'',',
'            answer_text  VARCHAR2(4000) PATH ''$.answer''  ',
'            ) ) jt;',
'  --.  ',
' -- DBMS_OUTPUT.PUT_LINE(''v_answer_json: '' || v_answer_json);',
' SELECT LISTAGG(''Question: '' || QUESTION || '' Answer: '' || ANSWER, '' '') WITHIN GROUP (ORDER BY TIMESTAMP ASC) ',
'    INTO v_context',
'FROM CHAT_HISTORY;',
'    ',
'   -- DBMS_OUTPUT.PUT_LINE(''v_context  : '' || v_context);',
'    if v_context is null then',
'        select dbms_vector_chain.utl_to_generate_text(',
'         ''You are an AI-powered chatbot that generates professional responses. You retrieve the most ',
'         accurate and relevant information from a database to provide high-quality answers. Do not include titles or references to this prompt in your response. ',
'         Ensure that your responses are clear, well-structured, and professional. This is the last question: '' || v_question_json || ''',
'        These are the answers retrieved from the database: '' || v_answer_json || ''',
'        If these answers do not make sense, please improve them.'',',
'         json(''{ "provider": "ocigenai",',
'                    "credential_name": "'' || p_credential ||''",',
'                    "url": "''|| p_endpoint_gen_text ||''",',
'                    "model": "''|| p_model_gen_text ||''"',
'                    }'')',
'            ) into v_final_response',
'            FROM dual;',
'',
'    else',
'        select dbms_vector_chain.utl_to_generate_text(',
'         ''You are an AI-powered chatbot that generates professional responses by considering previous questions and answers for context. Do not respond to previous questions; they are provided solely for context. Retrieve the most accurate and releva'
||'nt information from the database to provide high-quality answers. ',
'         Do not include titles or references to this prompt in your response. Ensure your responses are clear, well-structured, and professional.',
'        This is the last question: '' || v_question_json || ''',
'        These are the answers retrieved from the database: '' || v_answer_json || ''',
'        If these answers do not make sense, please improve them.',
'        These are the previous questions and answers: '' || v_context,',
'         json(''{ "provider": "ocigenai",',
'                    "credential_name": "'' || p_credential ||''",',
'                    "url": "''|| p_endpoint_gen_text ||''",',
'                    "model": "''|| p_model_gen_text ||''"',
'                    }'')',
'            ) into v_final_response',
'            FROM dual;',
'',
'    end if;',
'     -- Add the new question to chat history',
'    ADD_CHAT_CONTEXT(v_question_json, v_final_response);',
'    ',
'    return v_final_response;',
'',
'END;',
'',
'END MEETING_VAULT;',
'/',
'create or replace package body "AICD_AISPEECH" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide integration to OCI AI Speech Service, creation & monitoring of Speech Transcription Jobs and',
'--              retrieval of the job transcript that is loaded into the AICD_MEDIA table.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Function:      CREATE_JOB',
'-- Description: Creates an AI Speech Transcribe Job',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_lang_code           - Language Code of the language used in the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @b_request_status   - Status of the request',
'-- =============================================',
'FUNCTION CREATE_JOB(',
'    n_media_id      number,',
'    vc_filename     varchar2,',
'    vc_lang_code    varchar2,',
'    vc_request_url  varchar2,',
'    vc_speechcred   varchar2 default ''oci_credential''',
'    ) ',
'    RETURN varchar2',
'    IS',
'        c_body              clob;',
'        c_response          clob;',
'        vc_job_id           varchar2(200);',
'        vc_request_status   varchar2(200);',
'',
'    BEGIN',
'    SELECT',
'        JSON',
'            {',
'               ''compartmentId'' VALUE ac.compartment,',
'               ''displayName'' VALUE REPLACE(vc_filename,'' '',''-''),',
'               ''inputLocation'' VALUE ',
'               {',
'                  ''locationType'' VALUE ''OBJECT_LIST_INLINE_INPUT_LOCATION'',',
'                  ''objectLocations'' VALUE [ ',
'                  {',
'                     ''bucketName'' VALUE ac.input_location,',
'                     ''namespaceName'' VALUE ac.namespace,',
'                     ''objectNames'' VALUE [vc_filename]',
'                  }]',
'               },',
'               ''outputLocation'' VALUE',
'               {',
'                  ''bucketName'' VALUE ac.output_location,',
'                  ''namespaceName'' VALUE ac.namespace,',
'                  ''prefix'' VALUE ''whisper''',
'               },',
'               ''modelDetails'' VALUE',
'               {',
'                  ''languageCode'' VALUE vc_lang_code,',
'                  ''modelType'' VALUE ac.model,',
'                  ''transcriptionSettings'' VALUE',
'                  {',
'                     ''diarization'' VALUE ',
'                     {',
'                        ''isDiarizationEnabled'' VALUE ''true''',
'                     }',
'                  }',
'               }',
'            }',
'    INTO c_body',
'    FROM AICD_OCI_APP_CONFIGURATION ac;',
'',
'    APEX_DEBUG.INFO(''Body for Media  %s'', c_body);',
'',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'    APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'    c_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'        p_url                   => vc_request_url,',
'        p_http_method           => ''POST'',',
'        p_body                  => c_body,',
'        p_transfer_timeout      => 360,',
'        p_credential_static_id  => vc_speechcred',
'    );',
'',
'    -- Need to update AICD_MEDIA and set the url column',
'    vc_job_id           := JSON_VALUE(c_response,''$.id'');',
'    vc_request_status   := JSON_VALUE(c_response,''$.lifecycleState'');',
'',
'    -- Update AICD Media Table with job id and submitted status',
'    -- ** Should enclose in TRY/CATCH Block',
'    UPDATE AICD_MEDIA',
'    SET ',
'        PROCESS_JOB_ID  = vc_job_id,',
'        PROCESS_STATUS  = ''SUBMITTED''',
'    WHERE ID = n_media_id;',
'',
'    COMMIT;',
'',
'    RETURN vc_request_status;',
'    END CREATE_JOB;',
'',
'-- =============================================',
'-- Function:      GET_JOB_STATUS',
'-- Description: Get status of AI Speech Transcribe Job',
'-- Parameters:',
'--      @vc_job_id              - ID of the media object',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_STATUS(',
'        vc_job_id       varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential''',
'    ) ',
'    RETURN varchar2',
'    IS',
'        c_response          clob;',
'        vc_request_status   varchar2(200);',
'    BEGIN',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'        ',
'        c_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => vc_request_url || ''/'' || vc_job_id,',
'            p_http_method           => ''GET'',',
'            --p_body_blob             => ,',
'            p_credential_static_id  => vc_speechcred',
'        );',
'',
'        -- Need to update AICD_MEDIA and set the url column',
'        APEX_DEBUG.INFO(''Current Job ID %s'', vc_job_id);',
'        vc_request_status := JSON_VALUE(c_response,''$.lifecycleState'');    ',
'',
'        RETURN vc_request_status;',
'    END GET_JOB_STATUS;',
'',
'-- =============================================',
'-- Function:      GET_JOB_TRANSCRIPTION',
'-- Description: Retrieves AI Speech Transcribe Job Transcription and save it to the AICD_MEDIA table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_job_id              - ID of the media object',
'--      @vc_filename            - File name of the media object to transcribe',
'--      @vc_request_url         - AI Speech Service URL',
'--      @vc_speechcred          - Credential to be used for the AI Speech service innovaction',
'--      @vc_obstorcred          - Credential to be used for the Object Storage service innovaction',
'-- Returns: @vc_request_status  - Status of the request',
'-- =============================================',
'    FUNCTION GET_JOB_TRANSCRIPTION(',
'        n_media_id      number,',
'        vc_job_id       varchar2,',
'        vc_filename     varchar2,',
'        vc_request_url  varchar2,',
'        vc_speechcred   varchar2 default ''oci_credential'',',
'        vc_obstorcred   varchar2 default ''oci_credential''',
'    ) ',
'    RETURN varchar2',
'    IS',
'        c_response          clob;',
'        bl_transcription    blob;',
'        vc_file_url         varchar2(4000);',
'        vc_request_status   varchar2(200);',
'    BEGIN',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        c_response := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url                   => vc_request_url || ''/'' || vc_job_id,',
'            p_http_method           => ''GET'',',
'            p_credential_static_id  => vc_speechcred',
'        );',
'',
'        APEX_DEBUG.INFO(''Current status is %s'', JSON_VALUE(c_response,''$.lifecycleState''));',
'        DBMS_OUTPUT.PUT_LINE(''Current status is:'' || JSON_VALUE(c_response,''$.lifecycleState''));',
'',
'        SELECT ',
'            E.ENDPOINT || ''/n/'' || AC.NAMESPACE || ''/b/'' || AC.OUTPUT_LOCATION || ''/o/'' || replace(apex_util.url_encode(JSON_VALUE(c_response,''$.outputLocation.prefix'') || AC.NAMESPACE || ''_'' || AC.INPUT_LOCATION || ''_'' || vc_filename || ''.json''),''+'''
||',''%20'')',
'        INTO vc_file_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''os'';',
'',
'        APEX_DEBUG.INFO(''Requested: %s'',vc_file_url);',
'        DBMS_OUTPUT.PUT_LINE(''Requested: '' || vc_file_url);',
'',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name := ''Content-Type''; ',
'        APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := ''application/json'';',
'',
'        -- Save this to a table to be able to parse correctly.',
'        bl_transcription := apex_web_service.make_rest_request_b(',
'            p_url => vc_file_url,',
'            p_http_method => ''GET'',',
'            p_credential_static_id => vc_obstorcred',
'        );',
'',
'        DBMS_OUTPUT.PUT_LINE(''Transcript:'' || JSON_VALUE(bl_transcription,''$.transcriptions[0]''));',
'',
'        UPDATE AICD_MEDIA',
'        SET'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(14468723189526766)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' ',
'            TRANJSON = JSON(bl_transcription),',
'            TRANSCRIPT = (',
'                SELECT jt.transcript',
'                FROM JSON_TABLE (',
'                    bl_transcription, ''$.transcriptions[0]''',
'                    NULL ON EMPTY',
'                    COLUMNS',
'                    (',
'                        transcript      clob    path ''$.transcription''',
'                    )',
'                ) jt ',
'            )',
'',
'        WHERE',
'            ID = n_media_id;',
'',
'        COMMIT;',
'',
'        vc_request_status := ''SUCCESS'';',
'        ',
'        RETURN vc_request_status;',
'    END GET_JOB_TRANSCRIPTION;',
'',
'end "AICD_AISPEECH";',
'/',
'create or replace package body "AICD_DBMS_VECTOR" ',
'-- =============================================',
'-- Author:      Sydney Nurse@Oracle Switzerland',
'-- Author:      Jerome Francoisee@Oracle Belgium',
'-- Author:      Eloi Lopes@Oracle Spain',
'-- Create date: January 2025',
'-- Update Date: ',
'-- Description: ',
'--              Provide Vector Search Services, generating vectors, comparing input to data loaded the AICD_MEDIA & AICD_TRANSCRIPT_BLOCKS tables.',
'--              ',
'-- Deppendencies: None',
'-- =============================================',
'as',
'-- =============================================',
'-- Public Functions',
'-- =============================================',
'-- =============================================',
'-- Procedure:      GNERATE_VECTOR',
'-- Description: Creates an AI Speech Transcribe Job and updates the AICD_MEDIA Table',
'-- Parameters:',
'--      @n_media_id             - ID of the media object',
'--      @vc_mode                - Processing mode - media: info is stored in AICD_MEDIA, block:info is stored in AICD_TRANSCRIPT_BLOCKS, NULL: Text as parameter',
'--      @c_text                 - Text as Clob',
'--      @vc_embed_model         - LLM model used to generate embeddings',
'--      @vc_vectorcred          - Credential to be used for the Vector Speech',
'-- =============================================',
'    PROCEDURE GENERATE_VECTOR(',
'        n_media_id      NUMBER,',
'        vc_mode         VARCHAR2 DEFAULT NULL,',
'        c_text          CLOB DEFAULT NULL,',
'        vc_embed_model  VARCHAR2 DEFAULT ''cohere.embed-multilingual-v3.0'',',
'        vc_vectorcred   VARCHAR2',
'    )',
'    IS',
'        vc_request_url  VARCHAR2(400);',
'        c_block         CLOB;',
'    BEGIN',
'        ',
'        -- Get the Embeddings AI Endpoint',
'        SELECT ',
'            E.ENDPOINT || ''/20231130/actions/embedText''',
'        INTO vc_request_url',
'        FROM AICD_OCI_SERVICE_ENDPOINTS E, AICD_OCI_APP_CONFIGURATION AC, AICD_OCI_SERVICES S',
'        WHERE',
'            E.REGION = AC.REGION AND',
'            E.SERVICE = S.ID AND',
'            S.NAME = ''generative-ai-inference'';',
'',
'        APEX_DEBUG.INFO(''Processing Mode => %s using Credential => %s'',vc_mode,vc_vectorcred);',
'        ',
'        CASE LOWER(vc_mode)',
'        -- Generate Emmbeddings for Media',
'        WHEN ''media'' THEN',
'            UPDATE AICD_MEDIA',
'            SET',
'                VECTOR_TAGS     = ',
'                CASE ',
'                WHEN TAGS IS NOT NULL THEN ',
'                    dbms_vector_chain.utl_to_embedding(',
'                        TAGS,',
'                        json(''{',
'                        "provider": "ocigenai",',
'                        "credential_name": "'' || vc_vectorcred || ''",',
'                        "url": "'' || vc_request_url || ''",',
'                        "model": "'' || vc_embed_model || ''"',
'                        }''))',
'                END,',
'                VECTOR_SUMMARY  = ',
'                CASE ',
'                WHEN SUMMARY IS NOT NULL THEN',
'                    dbms_vector_chain.utl_to_embedding(',
'                        SUMMARY,',
'                        json(''{',
'                        "provider": "ocigenai",',
'                        "credential_name": "'' || vc_vectorcred || ''",',
'                        "url": "'' || vc_request_url || ''",',
'                        "model": "'' || vc_embed_model || ''"',
'                        }''))',
'                END',
'            WHERE',
'                ID = n_media_id;',
'        ',
'        -- Generate Emmbeddings for Transcript Blocks',
'        WHEN ''block'' THEN',
'            UPDATE AICD_TRANSCRIPT_BLOCKS',
'            SET',
'                VECTOR_BLOCK     = ',
'                    dbms_vector_chain.utl_to_embedding(',
'                        BLOCK,',
'                        json(''{',
'                        "provider": "ocigenai",',
'                        "credential_name": "'' || vc_vectorcred || ''",',
'                        "url": "'' || vc_request_url || ''",',
'                        "model": "'' || vc_embed_model || ''"',
'                        }''))',
'            WHERE',
'                MEDIA_ID = n_media_id;',
'        ',
'        -- Generate Emmbeddings for generic text',
'        WHEN IS NULL THEN',
'            NULL;',
'        ',
'        END CASE;',
'',
'        COMMIT;',
'    END GENERATE_VECTOR;',
'',
'end "AICD_DBMS_VECTOR";',
'/',
'create or replace package body "AICD_OBJSTORAGE" ',
'AS',
'',
'-- =============================================',
'-- Function:      REST_UTIL',
'-- Description: Utility to support Rest Calls, shared across all OCI REST Service calls',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials to use in the REST request',
'--      @l_vc_url               - The URL for the REST request ',
'--      @l_vc_method            - The HTTP method for the REST request',
'--      @l_vc_body              - The Body of the REST request',
'--      @l_vc_type              - The type of REST request [BLOB | CLOB]',
'-- Returns: @l_response         - The Rest Response                        ',
'-- =============================================',
'    FUNCTION REST_UTIL',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_url                in varchar2 default null,',
'        l_vc_method             in varchar2 default null,',
'        l_mime_type             in varchar2 default null,',
'        l_vc_body_c             in clob default empty_clob(),',
'        l_vc_body_b             in blob default empty_blob(),',
'        l_vc_type               in varchar2 default null',
'    )',
'    RETURN clob ',
'    IS ',
'        c_response      clob;',
'',
'    BEGIN',
'',
'        apex_web_service.g_request_headers.delete();',
'        apex_web_service.g_request_headers(1).name := ''Content-Type'';',
'        apex_web_service.g_request_headers(1).value := l_mime_type;',
'',
'        BEGIN',
'            CASE l_vc_type',
'                WHEN ''BLOB'' THEN                    ',
'                    c_response := apex_web_service.make_rest_request(',
'                        p_url                   => l_vc_url,',
'                        p_http_method           => l_vc_method,',
'                        p_body_blob             => l_vc_body_b,',
'                        p_transfer_timeout      => 360,',
'                        p_credential_static_id  => l_vc_credential',
'                    );',
'',
'                    for i in 1.. apex_web_service.g_request_headers.count',
'                    loop',
'                        apex_debug.info(''%s: %s'',apex_web_service.g_headers(i).name,apex_web_service.g_headers(i).value);',
'                    end loop;',
'                ',
'                WHEN ''CLOB'' THEN',
'                    c_response := apex_web_service.make_rest_request(',
'                        p_url                   => l_vc_url,',
'                        p_http_method           => l_vc_method,',
'                        p_body                  => l_vc_body_c,',
'                        p_credential_static_id  => l_vc_credential',
'                    );',
'                    ',
'                    ',
'            END CASE;',
'',
'        EXCEPTION',
'        WHEN OTHERS THEN',
'            APEX_DEBUG.INFO(''Failed submitting service call'');',
'            APEX_DEBUG.INFO(SQLCODE);',
'            APEX_DEBUG.INFO(SUBSTR(SQLERRM, 1, 200));',
'            APEX_DEBUG.INFO(c_response);',
'        END;',
'',
'        RETURN (c_response);',
'',
'    END REST_UTIL;',
'',
'-- =============================================',
'-- Procedure:      POST_OBJECT',
'-- Description: Description: Posts an Object to OCI Object Storage',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @l_vc_file_name         - The name of the object stored in the APEX_APPLICATION_TEMP_FILES',
'-- Returns:                         ',
'-- =============================================',
'    PROCEDURE POST_OBJECT',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        l_vc_file_name          in varchar2 default null',
'    )',
'    IS',
'        l_request_url           varchar2(32767);',
'        l_request_filename      varchar2(500);',
'        l_enc_filename          varchar2(4000);',
'        l_request_content       blob;',
'        l_mime_type             varchar2(200);',
'        l_response              clob;',
'        ',
'    BEGIN',
'        SELECT ',
'            blob_content,filename, mime_type ',
'        INTO ',
'            l_request_content,l_request_filename, l_mime_type ',
'        FROM apex_application_temp_files',
'        WHERE',
'            name = l_vc_file_name;',
'',
'        l_enc_filename := replace(apex_util.url_encode(l_request_filename),''+'',''%20'');',
'        ',
'        --l_request_url := ''https://objectstorage.'' || l_vc_region || ''/n/'' || l_vc_namespace || ''/b/'' || l_vc_bucket || ''/o/'' ||l_enc_filename;',
'',
'        SELECT ',
'            ENDPOINT || ''/n/'' || l_vc_namespace || ''/b/'' || l_vc_bucket || ''/o/'' ||l_enc_filename',
'        INTO l_request_url',
'        FROM AICD_OCI_REGIONAL_ENDPOINTS',
'        WHERE',
'            REGION  = l_vc_region AND',
'            SERVICE = ''os'';',
'',
'        APEX_DEBUG.INFO(''URL: %s'',l_request_url);',
'        APEX_DEBUG.INFO(''MIME Type: %s'',l_mime_type);',
'        ',
'        l_response := REST_UTIL',
'            (',
'                l_vc_credential         => l_vc_credential,',
'                l_vc_url                => l_request_url,',
'                l_vc_method             => ''PUT'',',
'                l_mime_type             => l_mime_type,',
'                l_vc_body_b             => l_request_content,',
'                l_vc_type               => ''BLOB''',
'            );',
'',
'    END POST_OBJECT;',
'',
'-- =============================================',
'-- Procedure:      MANAGE_OCI_BUCKETS',
'-- Description: Manage OCI Storage Buckets: LIST, CREATE, DELETE,',
'-- Parameters:',
'--      @l_vc_credential        - Name of the connection Credentials',
'--      @l_vc_region            - OCI Region in format of region.domain',
'--      @l_vc_namespace         - OCI Tenant Namespace',
'--      @l_vc_compartment_ocid  - OCI Compartment OCID',
'--      @l_vc_bucket            - OCI Object Storage Buckets',
'--      @vc_request_action      - The requested action ',
'--      @vc_session             - The current APEX session ',
'-- Returns:',
'-- Collections:',
'--                              - [APEX_SESSION]_OCI_BUCKETS_LIST',
'-- Calls:',
'-- Private functions:',
'--      REST_UTIL',
'-- =============================================',
'    PROCEDURE MANAGE_OCI_BUCKETS ',
'    (',
'        l_vc_credential         in varchar2 default null,',
'        l_vc_region             in varchar2 default null,',
'        l_vc_namespace          in varchar2 default null,',
'        l_vc_compartment_ocid   in varchar2 default null,',
'        l_vc_bucket             in varchar2 default null,',
'        vc_request_action       in varchar2 default null,',
'        vc_session              in varchar2 default null',
'    )',
'    IS',
'        l_request_url           varchar2(32767);',
'        l_body                  JSON_OBJECT_T;',
'        c_response              clob;',
'',
'        l_seq_id                number;',
'',
'    BEGIN',
'        --l_request_url := ''https://objectstorage.'' || l_vc_region || ''/n/'' || l_vc_namespace || ''/b/'';',
'',
'        SELECT ',
'            ENDPOINT || ''/n/'' || l_vc_namespace || ''/b/''',
'        INTO l_request_url',
'        FROM AICD_OCI_REGIONAL_ENDPOINTS',
'        WHERE',
'            REGION  = l_vc_region AND',
'            SERVICE = ''os'';',
'',
'        --APEX_DEBUG.INFO(''Request Action: %s on url %s'',vc_request_action, l_request_url);',
'    ',
'        CASE vc_request_action',
'            WHEN ''LIST'' THEN',
'                BEGIN',
'                    APEX_DEBUG.INFO(''Attempting to Get List of Buckets'');',
'                    ',
'                    c_response := REST_UTIL',
'                    (',
'                        l_vc_credential         => l_vc_credential,',
'                        l_vc_url                => l_request_url || ''?compartmentId='' || l_vc_compartment_ocid,',
'                        l_vc_method             => ''GET'',',
'                        l_vc_type               => ''CLOB''',
'                    );',
'                    ',
'                    -- Create or Trunacte the Collection',
'                    APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(vc_session || ''_OCI_BUCKETS_LIST'');',
'',
'                    FOR buckets IN (',
'                        SELECT BUCKET_NAME ',
'                        FROM JSON_TABLE(',
'                            c_response, ''$[*]''',
'                            NULL ON EMPTY',
'                            COLUMNS (',
'                                BUCKET_NAME  varchar2(255)   path ''$.name''',
'                            )',
'                        )',
'                    )',
'                    LOOP',
'                        -- C001 = BUCKET_NAME',
'                        APEX_COLLECTION.ADD_MEMBER(',
'                            p_collection_name   => vc_session || ''_OCI_BUCKETS_LIST'',',
'                            p_c001              => buckets.BUCKET_NAME',
'                        );',
'                    END LOOP;',
'                END;',
'',
'            WHEN ''CREATE'' THEN',
'                BEGIN',
'                    APEX_DEBUG.INFO(''Attempting to Create OCI Bucket'');',
'',
'                    l_body := JSON_OBJECT_T(''{}'');',
'                    l_body.put(''compartmentId'', l_vc_compartment_ocid);',
'                    l_body.put(''name'', l_vc_bucket);',
'',
'                    ',
'                    c_response := REST_UTIL',
'                    (',
'                        l_vc_credential         => l_vc_credential,',
'                        l_vc_url                => l_request_url,',
'                        l_vc_method             => ''POST'',',
'                        l_vc_body_c             => l_body.to_clob(),',
'                        l_vc_type               => ''CLOB''',
'                    );',
'',
'                    -- C001 = BUCKET_NAME',
'                    APEX_COLLECTION.ADD_MEMBER(',
'                        p_collection_name   => vc_session || ''_OCI_BUCKETS_LIST'',',
'                        p_c001              => l_vc_bucket',
'                    );',
'                END;',
'',
'            WHEN ''DELETE'' THEN',
'                BEGIN',
'                    APEX_DEBUG.INFO(''Attempting to Delete OCI Bucket'');',
'                    ',
'                    c_response := REST_UTIL',
'                    (',
'                        l_vc_credential         => l_vc_credential,',
'                        l_vc_url                => l_request_url || ''/'' || l_vc_bucket,',
'                        l_vc_method             => ''DELETE'',',
'                        l_vc_type               => ''CLOB''',
'                    );',
'',
'                    SELECT ',
'                        seq_id',
'                    INTO',
'                         l_seq_id',
'                    FROM ',
